def pair(value):
    assert '~' in value,value
    return tuple(x.strip() for x in value.split('~',1))

def U(title, mechanism, formula, expression, expected, unit, boundary, verify, failure, misconception):
    """Each line is an original worked teaching scenario, not a site operating value."""
    z,e=pair(title); mz,me=pair(mechanism); bz,be=pair(boundary); vz,ve=pair(verify); fz,fe=pair(failure)
    value=eval(expression,{'__builtins__':{}},{'sqrt':math.sqrt,'log':math.log,'exp':math.exp,'log10':math.log10,'pi':math.pi,'abs':abs,'min':min,'max':max})
    assert abs(value-expected)<=max(1e-6,abs(expected)*1e-5),(title,value,expected)
    shown=f'{value:.6g}'
    model=f'原創假想教學算例：{formula}；計算 {expression} = {shown} {unit}。適用限制：{bz}。~Original hypothetical teaching example: {formula}; calculation {expression} = {shown} {unit}. Applicability: {be}.'
    practice=f'在「{z}」的教學模型或試算表中先重現 {shown} {unit}，再依驗證任務改動一個輸入、保留其餘條件。對照「{fz}」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。~In the teaching model or spreadsheet for {e.lower()}, first reproduce {shown} {unit}, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario "{fe}" and submit baseline and changed values, units, and one measurement that distinguishes them.'
    return {'title':title,'mechanism':mechanism,'model':model,'verify':verify,'failure':failure,'misconception':misconception,'practice':practice,'_check':{'expression':expression,'expected':expected,'unit':unit,'description':title}}

