def institution_place(number):
    k={454:'usgs',462:'devb',463:'emsd',464:'doe',465:'doe',466:'envac',467:'tomra',468:'steinert',469:'tomra',470:'voith',471:'tomra',472:'efsa',473:'calrecycle',475:'fhwa'}.get(number,'epa')
    z,e,cz,ce,lat,lon,url=INSTITUTIONS[k]
    return {'name':z+'：方法資料來源機構（非實廠）','nameEn':e+': methodology source institution (not a process plant)','country':cz,'countryEn':ce,'lat':lat,'lon':lon,'coordinateScope':'近似機構所在區域位置；依公開地址作教材地圖代表點，非建物入口、實廠、實測或導航位置。','coordinateScopeEn':'Approximate institution-area location inferred from its public address for the teaching map; not a building entrance, process plant, surveyed point or navigation coordinate.','locationSourceUrl':url,'locationVerified':'2026-10-23'}

def C(number,focus,discipline,nodes,refs,units):
    cid=f'b{number}';target=TARGETS[cid];assert len(units)==10,(cid,len(units))
    fz,fe=pair(focus)
    checks=[u.pop('_check') for u in units]
    z=target['title'];e=target['titleEn']
    d={'id':cid,'title':z+'~'+e,'focus':focus,'discipline':discipline,
       'summary':f'以「{fz}」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。~Follow {fe.lower()} through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.',
       'units':units,'sources':[S[r] for r in refs],'architectureNodes':nodes,
       'place':institution_place(number),
       'history':'本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。~The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability.',
       'modelChecks':checks}
    out=BASE/'inputs'/f'{cid}.json';out.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
    print(cid,'10 units; 10 numeric checks',flush=True)

C(451,'離子遷移、極化與淡濃水收支~Ion transport, polarization and dilute/concentrate balances','environment-water',
 ['進流水~Feed','前處理~Pretreatment','離子交換膜堆~Ion-exchange stack','淡水槽~Diluate tank','濃水槽~Concentrate tank','監測與回收~Monitoring and recovery'],['reuse','ed'],[
 U('定義除鹽負荷~Define the desalination load','先把流量和鹽濃度轉成相同時間基準的質量流率；導電度只是在離子組成固定時的替代量。~Convert flow and salt concentration into a mass rate on one time basis; conductivity is a surrogate only for a stable ionic composition.','Q=20 m3/h; C=1.5 kg/m3; m=QC','20*1.5',30,'kg/h','穩態且忽略密度改變~Steady state with negligible density change','改變流量而固定鹽濃度，核對質量流率斜率。~Vary flow at fixed salinity and check the mass-rate slope.','只比較導電度會掩蓋流量增加造成的鹽負荷上升。~Conductivity alone hides a salt-load increase caused by higher flow.','濃度相同就代表每小時除鹽負荷相同。~Equal concentration means equal hourly salt load.'),
 U('電荷與離子當量~Charge and ionic equivalents','膜選擇性和電流效率把電荷流轉成有效離子輸送；以當量而非總離子莫耳直接計數。~Membrane selectivity and current efficiency convert charge into useful ionic transport; count charge equivalents rather than unweighted ion moles.','n_eq=eta I t/F; eta=0.9; I=10 A; t=3600 s; F=96485 C/mol','0.9*10*3600/96485',0.335803493,'mol-equivalent','單一膜對等效量，不乘未定義的膜數~Equivalent transfer for one cell pair; no undefined cell-count multiplier','改變電流並量測淡濃水離子收支，以反算效率。~Vary current and use dilute/concentrate ionic balances to infer efficiency.','把二價離子當成一價會低估所需電荷。~Treating divalent ions as monovalent underestimates charge demand.','一莫耳所有離子都只需一法拉第。~Every mole of ions requires exactly one Faraday.'),
 U('膜面積與電流密度~Membrane area and current density','總電流需除以有效膜面積；邊框、遮蔽與流道分布會讓局部電流密度高於平均。~Divide current by active membrane area; frames, masking and flow maldistribution can make local density exceed its average.','j=I/A; I=12 A; A=0.30 m2','12/0.30',40,'A/m2','平均值不代替局部極限電流試驗~An average does not replace a local limiting-current test','把有效面積減少10%，繪出平均電流密度變化。~Reduce active area by ten percent and plot mean current density.','用膜外框面積會把電流密度估得過低。~Using the frame area understates current density.','電流相同時膜面積不影響電流密度。~At equal current membrane area does not affect current density.'),
 U('濃差極化餘裕~Concentration-polarization margin','邊界層離子補給限制膜面電流；接近極限時升高電壓可能主要增加水分解和局部化學變化。~Boundary-layer ion supply limits membrane current; near the limit extra voltage can mainly increase water splitting and local chemistry changes.','margin=(jlim-j)/jlim; jlim=60; j=40 A/m2','(60-40)/60',0.333333333,'fraction','jlim 是假想量測結果，不是通用操作上限~The limiting current is a hypothetical measurement, not a universal operating limit','比較兩種流速的電流—電壓曲線，找出平台轉折。~Compare current-voltage curves at two flow velocities and locate the plateau transition.','以清水的極限值套用高污染進水，可能忽略結垢與流道阻塞。~Applying a clean-water limit to fouling feed ignores scaling and channel obstruction.','提高電壓必定同比提高有效除鹽量。~Raising voltage always proportionally raises useful desalination.'),
 U('堆疊電阻與電耗~Stack resistance and energy','膜、溶液與接觸構成等效電阻；電耗必須以產水量歸一化並納入電源效率。~Membrane, solution and contacts contribute resistance; normalize electrical use by product volume and include power-supply efficiency.','SEC=VI/(eta Q); V=100 V; I=10 A; eta=0.9; Q=5 m3/h; divide W by1000','100*10/(0.9*5*1000)',0.222222222,'kWh/m3','膜堆供電端輸入電耗，含電源損失但未含泵浦~Stack power-supply input electricity, including supply losses but excluding pumps','保持產水量，增加電阻並比較電壓和比電耗。~Hold production fixed, increase resistance, and compare voltage and specific energy.','把瓦特直接當千瓦時每立方公尺會錯用時間與流量單位。~Treating watts as kWh per cubic metre mixes time and flow units.','瞬時功率就是每立方公尺耗能。~Instantaneous power equals energy per cubic metre.'),
 U('水回收率與濃水~Water recovery and concentrate','回收率提高會把殘餘鹽分集中到較少濃水；產水品質和濃水處置必須同時檢核。~Higher recovery concentrates residual salt into less brine; check product quality and concentrate handling together.','Qc=Qf-Qp; Qf=10; Qp=7.5 m3/h','10-7.5',2.5,'m3/h','不考慮滲透水遷移與採樣損失的體積收支~Volume balance neglecting osmotic transfer and sample losses','把產水量由7.5改成8，重算濃水與鹽濃度。~Raise product flow from7.5 to8 and recalculate concentrate flow and salinity.','只報回收率可能隱藏濃水量減少後的結垢風險。~Recovery alone hides scaling risk as concentrate volume falls.','提高回收率不會改變濃水條件。~Higher recovery leaves concentrate conditions unchanged.'),
 U('淡濃水鹽平衡~Dilute-concentrate salt balance','用進料鹽流扣除產水鹽流求濃水濃度；此收支可抓出流量計或分析偏差。~Subtract product salt flow from feed salt flow to find brine concentration; this balance exposes flow-meter or analytical bias.','Cc=(Qf Cf-Qp Cp)/Qc; Qf=10,Cf=1,Qp=7.5,Cp=0.2,Qc=2.5','(10*1-7.5*0.2)/2.5',3.4,'kg/m3','穩態且鹽未沉澱~Steady state without salt precipitation','同時抽取三股流並保留取樣時刻。~Sample all three streams synchronously and retain timestamps.','非同步樣品在進水變動時會造成假的失衡。~Asynchronous samples create a false imbalance during feed changes.','只測淡水即可完成全堆鹽平衡。~Measuring diluate alone closes the stack salt balance.'),
 U('結垢趨勢與反轉~Scaling trends and reversal','極性反轉可調整膜面的離子累積，但不能取代硬度、鹼度與飽和度評估。~Polarity reversal changes ion accumulation at membrane surfaces but does not replace hardness, alkalinity or saturation assessment.','concentration factor=Cc/Cf=3.4/1','3.4/1',3.4,'ratio','濃縮倍率不是沉澱飽和指數~Concentration factor is not a precipitation saturation index','比較反轉前後壓差和電阻，區分流道阻塞與膜污染。~Compare pressure drop and resistance before/after reversal to distinguish channel blockage from membrane fouling.','把濃縮倍率直接當溶解度安全係數會漏掉離子活度效應。~Using concentration factor as a solubility safety factor misses activity effects.','只要使用反轉就不需要前處理。~Reversal eliminates the need for pretreatment.'),
 U('流道泵浦功率~Channel pumping power','增加流速可降低邊界層厚度，卻提高泵功；需比較總能耗而非只看堆電耗。~Higher velocity can thin the boundary layer while increasing pumping demand; compare total rather than stack-only energy.','P=DeltaP Q/eta; DeltaP=50000 Pa; Q=0.002 m3/s; eta=0.65','50000*0.002/0.65',153.8461538,'W','不可壓水流的泵輸入功率；eta為整體電至水效率~Pump input power for incompressible water; eta is overall wire-to-water efficiency','把流量加倍，另行量測壓差而非假設不變。~Double flow and measure pressure drop rather than assuming it stays fixed.','泵效率和堆效率混為一談會低估總耗電。~Confusing pump and stack efficiencies understates total electricity.','流速增加的能源成本永遠可忽略。~The energy cost of higher velocity is always negligible.'),
 U('產品異常的聯鎖證據~Evidence for product-quality interlocks','電導度突升、流量異常與電阻變化需要共同判讀；教學聯鎖應把不確定產水導向隔離狀態。~Interpret conductivity spikes, flow anomalies and resistance changes together; teaching interlocks divert uncertain product to an isolated state.','delay volume=Q t; Q=5 m3/h; t=30 s','5*30/3600',0.041666667,'m3','只計偵測延遲的流過體積，未含管線存水~Through-volume during detection delay only, excluding pipe inventory','注入假想感測延遲並追蹤受影響水量。~Inject a hypothetical sensor delay and track the affected volume.','忽略延遲會把警報之前的產水當作已驗證。~Ignoring delay treats pre-alarm product as verified.','警報發出後就代表之前所有產水均合格。~An alarm means all earlier product was acceptable.')])

C(452,'自由基曝露、光能與副產物證據~Radical exposure, photon energy and by-product evidence','environment-water',
 ['水質特性~Water matrix','氧化劑~Oxidant','光反應器~Photoreactor','接觸槽~Contact tank','殘餘淬熄~Residual quenching','分析驗證~Analytical verification'],['reuse','aop'],[
 U('目標污染物與背景水質~Target compound and matrix','微量目標物的消失率會受背景有機物與碳酸鹽競爭影響；先分開目標濃度和總氧化需求。~Background organics and carbonate compete for reactive species; distinguish target concentration from total oxidation demand.','load=Q C; Q=100 m3/h; C=2 microgram/L; 1 mg/m3=1 microgram/L','100*2',200,'mg/h','單一目標物質量負荷~Mass load of one target compound','固定目標物濃度，改變背景DOC比較反應速率。~Keep target concentration fixed and vary background DOC to compare reaction rate.','只依目標物質量估氧化劑可能漏掉主要清除劑。~Dosing from target mass alone misses dominant scavengers.','目標物濃度低就代表氧化需求必定低。~Low target concentration necessarily means low oxidation demand.'),
 U('擬一級降解模型~Pseudo-first-order decay','在氧化劑和水質近似固定的短時間區間，擬一級常數可概括觀測衰減；它不是分子本徵常數。~Over a short interval with nearly fixed oxidant and matrix, a pseudo-first-order constant summarizes observed decay; it is not an intrinsic molecular constant.','C/C0=exp(-k t); k=0.15 /min; t=10 min','exp(-0.15*10)',0.223130160,'fraction','不適用氧化劑耗盡或多相傳質主導區間~Not applicable when oxidant is depleted or multiphase transfer dominates','用半對數濃度圖檢查斜率是否近似固定。~Check for a near-constant slope on a semilog concentration plot.','彎曲衰減仍硬套單一常數會高估末段去除。~Forcing one constant onto curved decay can overpredict late removal.','擬一級常數與水質無關。~The pseudo-first-order constant is independent of water quality.'),
 U('所需反應時間~Required reaction time','目標去除倍數以自然對數進入一級時間式；十倍去除不等於十倍時間。~The natural logarithm of the removal ratio enters the first-order time expression; tenfold removal does not require tenfold time.','t=ln(C0/C)/k; ratio=10; k=0.15 /min','log(10)/0.15',15.35056729,'min','以已驗證的假想固定k為條件~Conditional on the validated hypothetical constant k','比較90%與99%去除的時間並說明對數關係。~Compare times for90% and99% removal and explain the logarithmic relation.','把log10直接代入自然對數式會少算時間。~Substituting log10 into a natural-log expression underestimates time.','90%和99%去除所需時間相同。~90% and99% removal take the same time.'),
 U('自由基競爭分率~Competition for radicals','不同清除途徑以反應速率貢獻競爭；目標分率小時單純加藥可能效率低。~Scavenging pathways compete through their rate contributions; a small target fraction makes simple dose escalation inefficient.','f_target=r_target/(r_target+r_background); values=2,18','2/(2+18)',0.1,'fraction','穩態自由基、僅兩個等效途徑~Steady-state radicals with two equivalent pathways','把背景清除速率減半並比較目標分率。~Halve background scavenging and compare the target fraction.','把總自由基產生量當成全部作用於目標會誇大去除。~Assigning all generated radicals to the target exaggerates removal.','所有自由基都會與目標污染物反應。~Every radical reacts with the target contaminant.'),
 U('紫外光透射與光程~UV transmission and path length','吸收使光強沿光程下降；同樣入口功率不代表每一流線得到相同光曝露。~Absorption reduces intensity along the optical path; equal input power does not give all flow paths equal exposure.','T=10^(-a L); a=0.15 /cm; L=2 cm','10**(-0.15*2)',0.501187234,'fraction','單波長均勻介質的吸收模型~Single-wavelength absorption in a homogeneous medium','改變光程，量測入口與出口光強。~Vary path length and measure entrance and exit intensity.','以入口光強乘停留時間會忽略陰影與吸收。~Multiplying inlet intensity by residence time ignores shadowing and absorption.','入口光強就是反應器內每一點的光強。~Inlet intensity equals intensity everywhere in the reactor.'),
 U('有效容積與停留時間~Active volume and residence time','死區與旁通會讓名目容積高估有效接觸；示蹤測試提供流動分布而非只一個平均。~Dead zones and bypass make nominal volume overstate contact; tracer testing reveals a distribution rather than just a mean.','t=Vactive/Q; Vactive=12 m3; Q=4 m3/min','12/4',3,'min','完全混合與栓流的降解式不同~Decay differs between mixed and plug-flow reactors','以脈衝示蹤比較早到峰與名目V/Q。~Compare an early tracer peak with nominal V/Q.','平均時間合理仍可能存在未充分處理的短路流。~A plausible mean can coexist with under-treated bypass flow.','平均停留時間達標就能排除所有短路流。~An acceptable mean residence time excludes every short circuit.'),
 U('單位對數去除電耗~Electrical energy per order','EEO把光源耗能除以處理水量與對數去除，用於固定邊界下比較；不能忽略泵與藥劑。~EEO normalizes light-source energy by volume and logarithmic removal for a fixed boundary; it does not erase pumping or reagent costs.','EEO=P t/[V log10(C0/C)]; P=2 kW;t=0.5 h;V=1 m3;ratio=10','2*0.5/(1*log10(10))',1,'kWh/m3/order','批次近似，僅所列電力邊界~Batch approximation with only the stated electricity boundary','比較相同去除倍數下不同處理容積的EEO。~Compare EEO at equal removal ratio for different treated volumes.','把照明效率與全系統效率混同會低報耗能。~Equating lamp efficiency with system efficiency understates energy.','去除百分比一樣就必定有相同EEO。~Equal percentage removal guarantees equal EEO.'),
 U('殘餘氧化劑與淬熄~Residual oxidant and quenching','採樣後殘餘氧化劑仍可能反應，造成樣品中濃度低於採樣時；淬熄需有空白與回收試驗。~Residual oxidant may react after sampling and lower measured concentration; quenching needs blanks and recovery tests.','residual mass=C V; C=0.4 mg/L; V=500 L','0.4*500',200,'mg','只算殘餘質量，不推定淬熄化學計量~Residual mass only; no assumed quench stoichiometry','比較立即淬熄、延遲淬熄與空白樣品。~Compare immediate quench, delayed quench and blanks.','未淬熄樣品會把瓶內持續反應誤當反應器效果。~An unquenched sample misattributes bottle reaction to reactor performance.','採樣離開反應器後化學反應必定立刻停止。~Chemical reactions always stop immediately after sampling.'),
 U('中間產物與碳收支~Intermediates and carbon balance','母體消失不等於礦化；追蹤中間產物、總有機碳和效應指標才能評估轉化。~Parent disappearance does not equal mineralization; track intermediates, TOC and effect measures to assess transformation.','TOC removal=(C0-C)/C0; C0=5,C=4 mgC/L','(5-4)/5',0.2,'fraction','TOC包含所有背景有機碳~TOC includes background organic carbon','把母體去除率與TOC去除率畫在同一圖上。~Plot parent and TOC removal on the same chart.','以99%母體去除宣稱99%礦化是不同指標混用。~Claiming99% mineralization from99% parent removal conflates metrics.','母體不見就代表全部轉成二氧化碳。~Disappearance of the parent means complete conversion to carbon dioxide.'),
 U('量測不確定度與放大~Uncertainty and scale-up','小試的光分布、混合與水質不能直接等比例放大；先量化資料誤差再建立相似條件。~Bench optical distribution, mixing and matrix do not scale proportionally; quantify measurement error and establish similarity first.','combined relative u=sqrt(u1^2+u2^2); u1=0.04;u2=0.03','sqrt(0.04**2+0.03**2)',0.05,'fraction','兩個獨立小誤差的均方根近似~Root-sum-square approximation for two independent small errors','比較不同光程試驗，記錄量測誤差和流動條件。~Compare tests at different path lengths with measurement error and flow conditions recorded.','只依容積比放大燈數會漏掉光程改變。~Scaling lamp count by volume alone misses changed optical paths.','小試容積乘十即可保證全尺度相同去除。~Tenfold bench volume guarantees identical full-scale removal.')])

C(453,'獨立障壁、量測界限與事件追溯~Independent barriers, measurement limits and event traceability','environment-water',
 ['來源風險~Source risks','處理鏈~Treatment train','障壁試驗~Barrier tests','即時監測~Online monitoring','隔離儲存~Isolation storage','證據台帳~Evidence ledger'],['reusebarrier','reuse'],[
 U('危害與用途分開~Separate hazards and uses','先列用途、暴露途徑與污染類型，再決定驗證指標；濁度不能代表所有化學與病原危害。~Define use, exposure route and contaminant classes before selecting validation measures; turbidity does not represent every chemical or microbial hazard.','coverage=assessed hazards/identified hazards; 8/10','8/10',0.8,'fraction','僅清單覆蓋率，不是安全機率~Checklist coverage only, not a safety probability','新增一項化學危害並重新檢查指標覆蓋。~Add a chemical hazard and reassess indicator coverage.','用一項出流水指標替代所有危害會造成盲區。~One effluent indicator leaves blind spots for other hazards.','濁度低即可證明所有危害均被控制。~Low turbidity proves control of all hazards.'),
 U('對數去除值~Log-removal value','LRV是進出濃度比的常用對數；必須有可比較樣品和分析範圍。~LRV is the base-ten logarithm of the inlet/outlet ratio; samples and analytical ranges must be comparable.','LRV=log10(Cin/Cout); Cin=10000; Cout=10 counts/L','log10(10000/10)',3,'log10','同一可量測指標與流態~Same measurable indicator and flow regime','把出水濃度增加十倍並比較LRV下降。~Increase outlet concentration tenfold and compare the LRV reduction.','把百分比去除相加會錯估多障壁效果。~Adding percentage removals misestimates multiple barriers.','99%去除就是3-log去除。~99% removal is3-log removal.'),
 U('檢出下限形成下界~Detection limit creates a bound','未檢出只能給濃度上界；由此得到的是LRV下界，不能宣稱無限去除。~Non-detection gives an upper concentration bound and hence a lower LRV bound, not infinite removal.','LRV_lower=log10(Cin/LOD); Cin=1000; LOD=1','log10(1000/1)',3,'log10 lower bound','LOD需用本次方法和基質驗證~LOD must be established for the method and matrix','將LOD降為0.1，重新寫出不等式而非點估計。~Lower LOD to0.1 and rewrite the inequality rather than a point estimate.','把未檢出填零會讓對數運算與風險判斷失真。~Entering zero for non-detection corrupts log calculations and interpretation.','未檢出等於濃度精確為零。~Non-detection means concentration is exactly zero.'),
 U('串聯障壁的條件~Conditions for serial barriers','在無旁通且各段驗證範圍成立時，濃度比可相乘、LRV可相加；共因失效須另算。~With no bypass and validated stage conditions, concentration ratios multiply and LRVs add; common-cause failures require separate treatment.','LRV_total=2+3+1','2+3+1',6,'log10','不含共因失效與未驗證操作區間~Excludes common-cause failure and unvalidated conditions','加入一條旁通路徑再比較相加法。~Introduce bypass and compare against simple addition.','共用電源失效時，名目獨立障壁可能同時失效。~A shared power failure can disable nominally independent barriers together.','任何三項標稱LRV都能無條件相加。~Any three nominal LRVs may be added unconditionally.'),
 U('旁通控制的極限~Bypass-limited performance','少量未處理旁通會支配最後濃度，即使主要處理線去除極佳。~A small untreated bypass can dominate final concentration even when the main treatment line performs well.','Cout/Cin=f+(1-f)*r; f=0.001;r=0.000001','0.001+(1-0.001)*0.000001',0.001000999,'fraction','完全混合的兩路流，忽略再生長~Two completely mixed streams without regrowth','把旁通率增加十倍，計算總LRV。~Increase bypass tenfold and calculate overall LRV.','只測主線出水會漏掉閥件或管路旁通。~Sampling only the main outlet misses valve or pipe bypass.','主線高LRV足以抵銷任意旁通。~High main-line LRV compensates for arbitrary bypass.'),
 U('代理指標與挑戰試驗~Surrogates and challenge tests','代理指標需與受控危害建立關係；挑戰試驗的粒徑、表面性質與水質會影響外推。~Relate surrogates to the controlled hazard; challenge-particle size, surface properties and matrix affect extrapolation.','recovery=measured spike/added spike; 85/100','85/100',0.85,'fraction','分析回收率不等於處理去除率~Analytical recovery is not treatment removal','在空白水與實際基質各做一次加標回收。~Run spike recovery in blank water and process matrix.','未修正分析損失會把假去除當障壁能力。~Unaccounted analytical loss looks like barrier removal.','代理物在所有水質下必定與病原完全相同。~A surrogate always behaves identically to the pathogen in every matrix.'),
 U('監測延遲與隔離容積~Monitoring delay and isolation volume','分析、通訊與閥切換延遲累積成未確認水量；需追蹤水團位置。~Analysis, communication and valve delays accumulate into unverified volume; track the water parcel.','V=Q(t_analysis+t_valve); Q=0.04 m3/s; times=60,10 s','0.04*(60+10)',2.8,'m3','不含管線與儲槽既有混合水~Excludes existing mixed inventory in pipes and tanks','延長分析時間並查明哪些水團需隔離。~Extend analysis delay and identify parcels requiring isolation.','只計閥門動作時間會低估未確認體積。~Using valve time alone understates unverified volume.','感測器警報沒有任何時間延遲。~Sensor alarms have no time delay.'),
 U('資料可用率與缺測~Availability and missing data','完整性需區分正常、校正、缺測與無效狀態；缺測不能自動視為合格。~Separate normal, calibration, missing and invalid states; missing data cannot automatically be accepted.','availability=valid minutes/total minutes; 1380/1440','1380/1440',0.958333333,'fraction','僅資料可用率，不是供水可用率~Data availability only, not water-service availability','將校正時段標為獨立狀態並重算有效資料率。~Mark calibration separately and recalculate valid-data fraction.','插值跨越失效事件可能掩蓋警報。~Interpolation across a failure event can conceal an alarm.','只要補值完整，就等於所有原始資料都有效。~A fully imputed series means all original observations were valid.'),
 U('共同原因與故障樹~Common causes and fault trees','若兩個障壁共用電源或校正偏差，乘上單獨失效率會高估可靠度。~Shared power or calibration bias invalidates multiplication of independent failure probabilities.','P_both_independent=p1*p2; p1=0.01;p2=0.02','0.01*0.02',0.0002,'probability','僅獨立假設的比較基準，非真實失效預測~Independent baseline only, not a real failure forecast','另加共因事件，畫出事件樹並避免重複計數。~Add a common-cause event and draw an event tree without double counting.','共用控制器故障可能讓兩條監測線同時報正常。~A shared controller fault can make two monitoring lines falsely report normal.','有兩個感測器就代表失效一定獨立。~Two sensors necessarily fail independently.'),
 U('驗證紀錄與變更管理~Validation records and change control','更換膜、演算法或量測方法可能超出原驗證範圍；證據需綁定版本與操作條件。~A changed membrane, algorithm or method may exceed the validated envelope; bind evidence to versions and conditions.','traceability=linked records/required records; 18/20','18/20',0.9,'fraction','文件完整性量，不代替水質證據~Documentation completeness, not water-quality evidence','移除一筆校正版本資料，說明哪些結論不能再追溯。~Remove one calibration-version record and identify conclusions that lose traceability.','舊版試驗結果不能無條件證明新設備效能。~Old tests do not unconditionally demonstrate new equipment performance.','只要設備名稱相同就不必評估任何變更。~An unchanged equipment name makes change review unnecessary.')])

C(454,'從校正標準到可追溯水質時序~From calibration standards to traceable water-quality series','environment-water',
 ['代表性取樣~Representative sampling','參考標準~Reference standards','感測器~Sensors','清潔與校正~Cleaning and calibration','修正與旗標~Corrections and flags','資料審核~Data review'],['usgs','usgsaudit'],[
 U('位置與樣品代表性~Location and sample representativeness','感測器讀到的是局部水團；流速、分層和旁流管延遲會改變代表性。~The sensor measures a local parcel; velocity, stratification and bypass delay affect representativeness.','delay=V/Q; V=2 L; Q=0.5 L/min','2/0.5',4,'min','理想旁流平均時間~Ideal mean bypass residence time','變更旁流量並比較事件到達時間。~Vary bypass flow and compare event arrival time.','停滯旁流管可能讓感測值落後於主流。~A stagnant bypass can lag the main stream.','感測器放在哪裡都會得到同一條時序。~Sensor location never changes the time series.'),
 U('兩點校正斜率~Two-point calibration slope','斜率校正把輸出尺度連回已知標準；零點與斜率必須分開估計。~Slope calibration ties output scale to known standards; estimate offset and slope separately.','m=(y2-y1)/(x2-x1); y1=1.1,y2=5.3;x1=1,x2=5','(5.3-1.1)/(5-1)',1.05,'output/input','線性區間的兩點估計~Two-point estimate within a linear range','增加第三個獨立標準檢查線性殘差。~Use a third independent standard to check linearity residual.','用兩點完全擬合不能證明全範圍線性。~Exact two-point fitting does not prove full-range linearity.','兩點校正即可證明所有濃度都沒有偏差。~Two-point calibration proves zero bias at every concentration.'),
 U('反算濃度與零點~Invert concentration and offset','已知y=mx+b時，應先扣b再除m；順序錯誤會留下系統偏差。~For y=mx+b subtract b before dividing by m; reversing the order leaves bias.','x=(y-b)/m; y=3.2;b=0.05;m=1.05','(3.2-0.05)/1.05',3,'input unit','線性模型且本次校正有效~Linear model with valid current calibration','對三筆模擬讀值套用正反轉換並比對。~Apply forward and inverse transforms to three simulated readings.','只乘修正係數而漏掉零點，低濃度誤差特別大。~A scale-only correction misses offset, especially at low concentration.','零點偏差可以一律用百分比修正。~Offset bias can always be corrected by a percentage.'),
 U('溫度補償的基準~Reference temperature compensation','導電度隨溫度變化；補償係數需符合水質與溫區，不能當所有感測器的通用公式。~Conductivity varies with temperature; its compensation coefficient depends on water and range and is not a universal sensor formula.','EC25=ECT/[1+alpha(T-25)]; ECT=1100;alpha=0.02;T=30','1100/(1+0.02*(30-25))',1000,'microS/cm','示範線性導電度補償~Illustrative linear conductivity compensation','固定鹽度，在兩個溫度檢查補償後是否一致。~Hold salinity fixed and compare compensated readings at two temperatures.','把補償後讀值再補償一次會重複修正。~Compensating an already corrected value applies the correction twice.','所有水質參數都可用同一溫度係數。~Every water-quality parameter uses the same temperature coefficient.'),
 U('清潔前後區分污損~Separate fouling using cleaning checks','保留清潔前、清潔後與標準液讀值，可區分污損與儀器漂移。~Retain pre-cleaning, post-cleaning and standard readings to separate fouling from instrument drift.','fouling shift=before-after; 8.4-8.0','8.4-8.0',0.4,'measurement unit','僅本次檢查差值，需結合時間序列判斷~Single-check difference requiring time-series context','先記錄再清潔，將差值放回最近維護區間。~Record before cleaning and map the difference onto the maintenance interval.','先清潔再讀值會遺失污損證據。~Cleaning before recording loses evidence of fouling.','清潔後正常即可證明之前所有讀值都正常。~A normal post-cleaning reading proves all earlier readings were normal.'),
 U('漂移率與時間插值~Drift rate and time interpolation','線性漂移修正僅在有證據支持時使用；突發故障不能用直線跨過。~Use linear drift correction only when supported; do not interpolate a line across an abrupt failure.','drift rate=(end-start)/days; (0.3-0.1)/10','(0.3-0.1)/10',0.02,'unit/day','假設平滑線性漂移~Assumes smooth linear drift','加入一次跳變，說明線性校正何處失效。~Insert a step change and identify where linear correction fails.','沒有維護紀錄的回溯直線可能製造假趨勢。~A retrospective line without maintenance records can create a false trend.','所有漂移都一定是線性的。~Every drift is linear.'),
 U('重複性與平均的不確定度~Repeatability and uncertainty of the mean','重複量測可估隨機變動，但多次讀取同一偏移不會消除系統誤差。~Repeated measurements estimate random variation; repeated readings of one bias do not remove systematic error.','u_mean=s/sqrt(n); s=0.2;n=16','0.2/sqrt(16)',0.05,'unit','獨立同分布量測，非高度自相關串流~Independent identically distributed readings, not strongly autocorrelated streams','比較連續密集讀值與間隔取樣的自相關。~Compare autocorrelation of dense readings and spaced samples.','把高度自相關的100筆視為100個獨立樣本會低估誤差。~Treating100 autocorrelated readings as100 independent samples understates uncertainty.','重複次數夠多就能消除任何校正偏差。~Enough repeats eliminate any calibration bias.'),
 U('響應時間與低通效應~Response time and low-pass behaviour','感測器的時間常數會平滑短事件；慢感測器的低峰值不等於污染峰不存在。~A sensor time constant smooths brief events; a lower peak from a slow sensor does not prove the event was absent.','fraction=1-exp(-t/tau);t=30 s;tau=10 s','1-exp(-30/10)',0.950212932,'fraction','一階階躍響應~First-order step response','用10秒脈衝與長階躍比較可觀測峰值。~Compare a10-second pulse with a sustained step.','只用穩態校正忽略動態誤差會錯過短脈衝。~Steady calibration alone misses dynamic error in short pulses.','穩態校正通過就代表短事件讀值完全正確。~Passing static calibration guarantees accurate short-event readings.'),
 U('離群值旗標與原始保留~Flag outliers and retain raw data','超界、維護與斷線屬不同原因；保留原始值、修正值與理由，使人工審核可重現。~Range errors, maintenance and disconnection are different causes; preserve raw values, corrected values and reasons for reproducible review.','flagged fraction=12/288','12/288',0.041666667,'fraction','五分鐘採樣一天的示例~Illustrative day of five-minute sampling','將校正時段和真正尖峰使用不同旗標。~Assign separate flags to calibration periods and genuine spikes.','自動刪掉所有尖峰可能刪除真實事件。~Automatically deleting all spikes can remove real events.','凡是偏離平均的資料都應刪除。~Every value far from the mean should be deleted.'),
 U('版本化與交接~Versioning and handover','校正係數、標準批號與維護日期需要和資料版本一起保存；輸出不能只留平滑後曲線。~Store calibration coefficients, standard batch and maintenance date with the data version; retain more than a smoothed output curve.','audit completeness=19/20','19/20',0.95,'fraction','證據完整性而非準確度~Evidence completeness rather than accuracy','從一個報表點追溯到原始讀值與當時係數。~Trace one report point to the raw reading and contemporaneous coefficients.','使用最新係數改寫所有歷史資料會改變過去的量測基準。~Applying the latest coefficients to all history changes the historical measurement basis.','只存最後校正係數就足以重現所有歷史結果。~Keeping only the latest coefficients reproduces every historical result.')])

C(455,'水力停留、氧化還原與季節性淨化~Hydraulic residence, redox and seasonal treatment','environment-water',
 ['沉砂前處理~Pretreatment','均勻配水~Flow distribution','介質與根區~Media and root zone','集水排放~Collection','採樣井~Sampling wells','維護~Maintenance'],['wetlands','wetlandmanual'],[
 U('負荷與功能定位~Load and treatment function','人工濕地是受水力與污染負荷限制的處理單元；面積綠化不能直接代表淨化能力。~A treatment wetland is constrained by hydraulic and pollutant loading; green area alone does not establish treatment capacity.','organic load=Q C/1000;Q=100 m3/day;C=80 mg/L','100*80/1000',8,'kg/day','進料BOD示例，不預設去除率~Illustrative influent BOD load without assumed removal','保持濃度，將流量加倍比較負荷。~Keep concentration fixed and double flow to compare loading.','只依面積比例增加進水可能超出氧與水力能力。~Increasing feed by area ratio alone can exceed oxygen or hydraulic capacity.','濕地只要有植物就能處理任意污染負荷。~Vegetation alone enables any pollutant load.'),
 U('孔隙水有效容積~Effective pore-water volume','地下流濕地的有效水量由介質孔隙率與飽和深度決定，不等於挖方總體積。~Water volume in a subsurface wetland depends on porosity and saturated depth, not total excavation volume.','Vw=A d n;A=500 m2;d=0.6 m;n=0.35','500*0.6*0.35',105,'m3','均一飽和介質，未考慮死區~Uniform saturated media without dead zones','改變孔隙率並比較停留時間。~Vary porosity and compare residence time.','以總體積代替孔隙水體積會高估接觸時間。~Using bulk volume overstates contact time.','介質中的石頭體積也算可流動水量。~Solid media volume counts as mobile water.'),
 U('水力停留與短流~Residence time and short circuiting','名目停留時間需由示蹤分布檢查；配水不均會造成局部高流速通道。~Check nominal residence time against tracer distribution; poor distribution creates fast preferential channels.','t=Vw/Q;105 m3/35 m3/day','105/35',3,'day','名目平均值，非最短水團時間~Nominal mean, not minimum parcel travel time','比較多個出水口示蹤峰值與回收量。~Compare tracer peaks and recovery at several outlets.','單點採樣可能漏掉高濃度短流。~A single sample may miss concentrated short-circuit flow.','平均停留三天代表每個水分子都停三天。~A three-day mean means every molecule stays exactly three days.'),
 U('面積負荷與經驗模型~Areal loading and empirical models','面積反應係數把複雜機制濃縮成經驗參數，需對應污染物、溫度與流態。~An areal coefficient summarizes complex mechanisms empirically and depends on pollutant, temperature and flow regime.','Cout=Cin exp(-kA A/Q);Cin=40 mg/L;kA=0.05 m/day;A=500;Q=50','40*exp(-0.05*500/50)',24.26122639,'mg/L','無背景濃度的教學栓流模型~Teaching plug-flow model with zero background concentration','比較面積加倍與流量減半的模型結果。~Compare doubled area with halved flow in the model.','將另一氣候的係數直接搬用會失去校正依據。~Transferring a coefficient from another climate loses calibration support.','同一個kA可用於所有污染物和季節。~One kA applies to every pollutant and season.'),
 U('達西流與水位差~Darcy flow and head difference','介質導水性與坡降決定可通過水量；堵塞後即使污染負荷不變也會回水。~Conductivity and gradient determine flow capacity; clogging can cause backing-up even at unchanged pollutant load.','Q=K Aflow i;K=100 m/day;Aflow=3 m2;i=0.01','100*3*0.01',3,'m3/day','飽和均質介質的達西近似~Darcy approximation for saturated homogeneous media','將導水係數減半並估所需水位差。~Halve conductivity and estimate required head difference.','忽略堵塞造成的K下降會低估水位。~Ignoring a clogging-induced reduction in K understates water level.','濕地介質的導水係數永遠不會改變。~Wetland-media conductivity never changes.'),
 U('氮轉化與氧需求~Nitrogen conversion and oxygen demand','硝化需氧而反硝化需電子供體與缺氧區；兩者不能僅靠種植物保證。~Nitrification needs oxygen while denitrification needs an electron donor and anoxic zones; vegetation alone guarantees neither.','O2 demand=4.57 mNH4N; mNH4N=2 kgN/day','4.57*2',9.14,'kgO2/day','理想化硝化化學計量，忽略生物合成~Idealized nitrification stoichiometry excluding biomass synthesis','比較氧供給與氨氮負荷，找出限制環節。~Compare oxygen supply with ammonia load to identify the limiting step.','將總氮降低全歸因植物吸收會忽略微生物路徑。~Attributing all nitrogen loss to plant uptake ignores microbial pathways.','所有濕地都同時具有無限硝化和反硝化能力。~Every wetland has unlimited nitrification and denitrification capacity.'),
 U('介質吸附容量~Media sorption capacity','磷等物質可能被介質暫存，容量耗盡後會突破；短期去除不等於永久移除。~Media may temporarily retain phosphorus; exhaustion causes breakthrough, so short-term removal is not permanent elimination.','capacity=M q;M=2000 kg;q=0.5 g/kg','2000*0.5/1000',1,'kg','假想可利用容量，需批次與柱試驗確認~Hypothetical usable capacity requiring batch and column tests','用累積負荷估容量使用比例並比較出水突破。~Estimate capacity use from cumulative load and compare outlet breakthrough.','以初期高去除外推多年會漏掉飽和。~Extrapolating high startup removal for years misses saturation.','吸附介質的容量永遠不會用盡。~Sorption-media capacity never runs out.'),
 U('蒸散與降雨收支~Evapotranspiration and rainfall balance','降雨、蒸散和滲漏都會改變出水量；濃度變高可能源自水分流失而非污染增加。~Rainfall, evapotranspiration and leakage alter outflow; higher concentration may result from water loss rather than increased pollutant mass.','Qout=Qin+P A-ET A;Qin=50;P=0.002;ET=0.005;A=500','50+0.002*500-0.005*500',48.5,'m3/day','無儲水變動、無滲漏的日平均~Daily mean without storage change or leakage','把乾季與雨季水量及質量收支分開。~Separate dry-season and wet-season water and mass balances.','只比較進出濃度會誤判稀釋或濃縮。~Concentration-only comparison misreads dilution or concentration.','濃度下降必定等於污染物質量被移除。~Lower concentration necessarily means pollutant mass was removed.'),
 U('沉積與維護週期~Sediment accumulation and maintenance','前處理攔住顆粒可延緩根區堵塞；維護依沉積與水位趨勢安排。~Pretreatment intercepts solids and delays root-zone clogging; schedule maintenance from sediment and head trends.','deposited volume=M/rho;M=600 kg;rho=1200 kg/m3','600/1200',0.5,'m3','沉積乾質量與假想堆積密度~Dry sediment mass with assumed bulk density','比較前處理去除率改變後的累積沉積量。~Compare sediment accumulation when pretreatment removal changes.','堵塞後才清理可能迫使系統旁通。~Waiting for blockage can force system bypass.','人工濕地建好後完全不需要維護。~A constructed wetland requires no maintenance after construction.'),
 U('季節驗證與生態目標~Seasonal validation and ecological goals','生物處理、棲地與排放功能須分別量測；單次晴天樣品不能代表全年。~Measure treatment, habitat and discharge functions separately; one dry-weather sample cannot represent a year.','seasonal coverage=sampled months/12;9/12','9/12',0.75,'fraction','採樣覆蓋率，不是處理達標率~Sampling coverage, not treatment compliance','設計跨季節與暴雨事件採樣表，保留空缺原因。~Design seasonal and storm-event sampling with reasons for gaps.','以夏季最佳表現作全年保證會忽略低溫與暴雨。~Using summer best performance as an annual guarantee ignores cold and storm periods.','一次出水合格即可證明全年所有條件都合格。~One acceptable effluent sample proves acceptability under all annual conditions.')])

C(456,'綠屋頂的水、重量與防水界面~Water, weight and waterproofing interfaces in green roofs','environment-urban',
 ['屋面結構~Roof structure','防水與阻根~Waterproofing and root barrier','排水層~Drainage layer','介質~Growing medium','植栽~Vegetation','溢流與檢修~Overflow and inspection'],['green','swmm'],[
 U('屋面集水邊界~Roof catchment boundary','依分水坡度定義每一排水口的集水面積；不得把相鄰區域重複計入或漏掉。~Define each outlet catchment from roof slopes without omissions or double counting.','V=P A;P=0.025 m;A=200 m2','0.025*200',5,'m3','一場均勻降雨，未扣截留~One uniform storm before interception losses','沿屋面坡向標示200m2的集水邊界。~Map the200m2 catchment along roof slopes.','排水分區錯置會低估個別排水口流量。~Incorrect drainage zoning understates individual outlet flows.','整棟屋頂只有總面積重要，各口分區可忽略。~Only total roof area matters; outlet catchments can be ignored.'),
 U('飽和載重~Saturated loading','植物、介質與滯留水都增加屋頂重量；乾介質重量不能代表暴雨後載重。~Vegetation, substrate and retained water add roof weight; dry substrate does not represent post-storm loading.','mass per area=rho_sat d;rho_sat=1200 kg/m3;d=0.12 m','1200*0.12',144,'kg/m2','只計介質，其他層與活載另列~Substrate only; other layers and live loads separate','列出各層飽和質量，與結構設計資料對照。~List saturated layer masses and compare with structural design data.','以乾密度檢核結構會漏掉蓄水重量。~Checking with dry density omits stored-water mass.','植物越輕就代表整個綠屋頂沒有額外荷重。~Light vegetation means the entire green roof has no extra load.'),
 U('可用蓄水量~Available storage','可用水容積取決於初始含水率與可達含水率差；同一屋頂在連續雨天容量不同。~Available storage depends on the gap between initial and attainable moisture; successive storms have different capacity.','S=A d DeltaTheta;A=200;d=0.12;DeltaTheta=0.15','200*0.12*0.15',3.6,'m3','均勻介質且忽略優先流~Uniform medium without preferential flow','把初始含水率提高，重算剩餘容量。~Raise initial moisture and recalculate remaining storage.','連續降雨時沿用乾屋頂容量會高估滯洪。~Using dry-roof capacity during repeated storms overstates retention.','每場雨開始前屋頂都會自動恢復乾燥。~The roof automatically dries before every storm.'),
 U('排水與溢流分流~Drainage and overflow routing','主排水和緊急溢流需有不同故障路徑；植栽層不能遮住檢修口。~Primary drainage and emergency overflow need distinct failure paths; planting must not obstruct access.','Qnet=Qrain-Qdrain;Qrain=4;Qdrain=2.5 L/s','4-2.5',1.5,'L/s','假想瞬時收支，不能代替管徑設計~Hypothetical instantaneous balance, not pipe sizing','封閉一個教學排水口，觀察水位與溢流路徑。~Close one simulated outlet and observe ponding and overflow.','主排水堵塞而溢流同樣受阻會造成積水增重。~Blocking both primary drain and overflow adds ponded load.','有綠化層就不需要緊急溢流。~A vegetated layer removes the need for emergency overflow.'),
 U('防水搭接與穿孔~Waterproofing joints and penetrations','滲漏常沿穿孔、收頭或搭接界面發生；水停留越久，缺陷曝露越長。~Leaks often follow penetrations, terminations or joints; longer ponding extends defect exposure.','hydrostatic pressure=rho g h;rho=1000;g=9.81;h=0.08 m','1000*9.81*0.08',784.8,'Pa','靜水壓，非防水層合格門檻~Hydrostatic pressure, not a waterproofing acceptance threshold','在模型標記穿孔並比較不同水深的壓力。~Mark penetrations in the model and compare pressures at different depths.','看不到室內滴水不代表防水層沒有局部受損。~No indoor dripping does not prove the membrane is intact.','介質可以取代連續防水層。~Growing medium can replace continuous waterproofing.'),
 U('過濾層與介質流失~Filter layer and media loss','過濾層需同時保留細粒並允許排水；過密或破損都會改變水路。~A filter must retain fines while allowing drainage; excessive tightness or tears change flow paths.','fines export=C V;C=0.02 kg/m3;V=5 m3','0.02*5',0.1,'kg','假想單場出流水固體負荷~Hypothetical solids export for one storm','採集排水測懸浮固體，對照介質表面沉陷。~Measure solids in drainage and compare surface settlement.','濾層堵塞會造成上方積水，破損則使介質流失。~A clogged filter ponds water; a torn filter loses media.','過濾層孔隙越小永遠越好。~Smaller filter pores are always better.'),
 U('蒸散恢復容量~Evapotranspiration restores capacity','蒸散在乾燥間隔恢復部分容量，但受植物、氣候和水分限制。~Evapotranspiration restores part of storage during dry intervals but is limited by plants, weather and moisture.','V_ET=ET A days;ET=0.003 m/day;A=200;days=2','0.003*200*2',1.2,'m3','固定日蒸散的簡化估算~Simplified constant daily evapotranspiration','比較一天與三天乾燥間隔的下場雨容量。~Compare next-storm capacity after one versus three dry days.','將潛在蒸散當實際值會高估乾燥恢復。~Using potential as actual evapotranspiration overstates recovery.','任何氣候下蒸散都固定不變。~Evapotranspiration is constant in every climate.'),
 U('土壤濕度感測~Substrate moisture sensing','感測器需對介質校正；有機質與鹽分會影響介電讀值。~Calibrate sensors to the substrate; organic content and salts affect dielectric readings.','water depth=theta d;theta=0.25;d=0.12 m','0.25*0.12*1000',30,'mm','均勻體積含水率~Uniform volumetric moisture','用秤重法與感測值在三種含水率下比較。~Compare gravimetric and sensor estimates at three moisture levels.','使用礦質土校正於輕質介質可能有系統偏差。~Using mineral-soil calibration for lightweight substrate introduces bias.','任何土壤濕度感測器出廠後都不需介質校正。~Factory calibration is sufficient for every substrate.'),
 U('降雨削峰與時間步長~Peak attenuation and time step','削峰要比較時間對齊的進出流量；總截留量不能代替峰值分析。~Compare time-aligned inflow and outflow for peak attenuation; retention volume is not a peak metric.','peak reduction=(Qin_peak-Qout_peak)/Qin_peak;5,3','(5-3)/5',0.4,'fraction','同一場事件和採樣頻率~Same event and sampling frequency','以1分鐘及15分鐘資料比較峰值遺失程度。~Compare peak loss using one- and15-minute data.','低頻平均值可能把真正的排水尖峰抹平。~Low-frequency averaging can erase actual drainage peaks.','截留40%雨量必定代表削峰40%。~Retaining40% of rainfall necessarily cuts peak flow40%.'),
 U('檢修台帳與季節巡查~Inspection ledger and seasonal checks','排水口、植栽覆蓋、防水收頭需分項紀錄；修補後要追蹤事件表現。~Record outlets, vegetation cover and membrane terminations separately and monitor events after repair.','coverage=checked outlets/total;11/12','11/12',0.916666667,'fraction','巡查覆蓋率，非防水可靠度~Inspection coverage, not waterproofing reliability','把未檢查的排水口列成待辦並保留位置照片。~Track unchecked outlets as tasks with location photos.','以外觀綠意判定排水良好會漏掉隱蔽堵塞。~Green appearance can conceal blocked drains.','植物長得好就能證明防水和排水都正常。~Healthy vegetation proves both waterproofing and drainage are sound.')])

C(457,'從街道逕流到雨水花園的滯留與處理~Detention and treatment from street runoff to rain gardens','environment-urban',
 ['集水街道~Street catchment','截流入口~Inlet','前置沉砂~Sediment forebay','植栽介質~Bioretention media','底排與滲透~Underdrain and infiltration','溢流~Overflow'],['rain','swmm'],[
 U('逕流體積~Runoff volume','不透水面積與有效降雨決定進入花園的體積；逕流係數是事件近似。~Impervious area and effective rainfall set incoming volume; a runoff coefficient is an event approximation.','V=C P A;C=0.9;P=0.03 m;A=1000 m2','0.9*0.03*1000',27,'m3','未模擬時間分布~No time distribution modeled','把面積分成屋頂與道路並分別估逕流。~Separate roof and road areas and estimate runoff independently.','只以花園自身面積算雨量會漏掉外來匯流。~Using garden area alone omits external runoff.','雨水花園只接收落在自己面積上的雨。~A rain garden receives only rainfall on its own area.'),
 U('入口截流能力~Inlet interception','道路邊溝水流不一定全部進入開口，入口坡度、堵塞和旁通需分開表示。~Not all gutter flow enters an opening; represent slope, blockage and bypass separately.','captured volume=f V;f=0.8;V=27','0.8*27',21.6,'m3','假想固定截流率~Hypothetical fixed interception fraction','減半入口開口並觀察旁通比例。~Halve the inlet opening and observe bypass fraction.','把總逕流當全部入園會高估實際處理量。~Assuming all runoff enters overstates treated volume.','只要設一個入口就能截住全部道路逕流。~One inlet captures all road runoff.'),
 U('表面滯留深度~Surface ponding depth','表面容量由有效平面積與可用水深決定，邊坡與自由高需另列。~Surface storage depends on effective area and usable depth; side slopes and freeboard are separate.','V=A h;A=80 m2;h=0.2 m','80*0.2',16,'m3','矩形容量近似~Rectangular storage approximation','改變花園有效面積並繪出容量。~Vary effective garden area and plot storage.','把自由高也算進日常容量可能消耗溢流保護。~Counting freeboard as routine storage consumes overflow protection.','所有邊緣高度都可當作正常滯留水深。~All edge height can count as normal ponding depth.'),
 U('介質可排水孔隙~Drainable media pores','介質蓄水取決於可排水孔隙而非總孔隙；已有水分會占用容量。~Media storage depends on drainable rather than total porosity; antecedent water occupies capacity.','V=A d nd;A=80;d=0.5;nd=0.15','80*0.5*0.15',6,'m3','均質介質~Homogeneous medium','比較乾期與連續雨期的孔隙容量。~Compare pore storage after dry and repeated-rain periods.','使用總孔隙率會把不可排水部分重複計入。~Total porosity overcounts non-drainable water.','總孔隙率與可排水孔隙率永遠相同。~Total and drainable porosity are always equal.'),
 U('入滲與退水~Infiltration and drawdown','退水速率受最慢土層、地下水與水頭影響；表面無水不代表介質已恢復容量。~Drawdown depends on the slowest layer, groundwater and head; a dry surface does not mean restored media storage.','time=V/(f A);V=16;f=0.01 m/h;A=80','16/(0.01*80)',20,'h','固定入滲率，未含底排~Constant infiltration rate without underdrain','將入滲率減半，檢查下一場雨前是否退水。~Halve infiltration and check drawdown before the next storm.','只量表土入滲可能漏掉下方低滲層。~Surface testing can miss a less permeable lower layer.','表土滲得快就代表整個剖面都滲得快。~Fast surface infiltration guarantees a permeable whole profile.'),
 U('底排與尾水~Underdrain and tailwater','底排流量受下游水位影響；淹沒出口時不能沿用自由出流能力。~Underdrain discharge depends on tailwater; submerged outlets cannot use free-outflow capacity.','net head=h_up-h_down;0.30-0.18','0.30-0.18',0.12,'m','只算可用水頭~Available head only','提高下游水位並比較水頭與排水。~Raise tailwater and compare head and discharge.','下游暴雨同時頂托會延長花園積水。~Storm tailwater can prolong ponding.','底排管只要存在就永遠能自由排水。~An underdrain always flows freely merely because it exists.'),
 U('顆粒截留與前池~Solids capture and forebay','前池先攔較粗顆粒，保護主介質；需以質量負荷而非濁度單點排維護。~A forebay captures coarse solids and protects media; base maintenance on mass load rather than one turbidity reading.','captured solids=C V eta;C=0.15 kg/m3;V=21.6;eta=0.6','0.15*21.6*0.6',1.944,'kg/event','假想事件平均濃度~Hypothetical event-mean concentration','比較前池清理前後入口沉積位置。~Compare deposition before and after forebay cleaning.','前池滿載會把沉積物重新帶入介質。~A full forebay can remobilize sediment into media.','截留的固體會自行消失而不需清除。~Captured solids disappear without removal.'),
 U('養分與介質釋出~Nutrients and media release','介質可吸附也可釋出養分；有機質增加不一定提高所有出流水質。~Media can retain or release nutrients; adding organic matter does not improve every water-quality measure.','net export=Qout Cout-Qin Cin;Qout=15,Cout=0.3,Qin=20,Cin=0.1','15*0.3-20*0.1',2.5,'g/event','C以mg/L、Q以m3；乘積為g~C in mg/L and volume in m3 yield grams','比較新介質與沖洗後介質的溶解磷。~Compare dissolved phosphorus from fresh and conditioned media.','只報總流量降低會漏掉濃度上升造成的養分輸出。~Volume reduction can hide nutrient export caused by higher concentration.','所有綠色介質都只會吸附不會釋出污染物。~All green media only adsorb and never release pollutants.'),
 U('溢流與安全通路~Overflow and safe routing','超過容量的雨水需走預定路徑；控制溢流位置比宣稱不溢流更可驗證。~Excess rainfall needs a planned route; overflow location is more verifiable than a claim of no overflow.','overflow=Vin-storage-infiltration;Vin=40;storage=22;infiltration=5','40-22-5',13,'m3','單事件桶模型~Single-event bucket model','用超設計事件追蹤溢流是否進入行人通道。~Track overflow during an extreme teaching event and check pedestrian paths.','入口堵塞或邊界破口會形成非預定水路。~Blocked inlets or boundary breaches create unintended flow paths.','雨水花園能完全消除所有洪水。~Rain gardens eliminate every flood.'),
 U('事件監測與維護觸發~Event monitoring and maintenance triggers','以退水時間、入出流與照片建立趨勢；維護觸發值須依場址設計而定。~Track drawdown, flows and photos; maintenance triggers depend on the site design.','relative drawdown increase=(30-20)/20','(30-20)/20',0.5,'fraction','假想前後比較，非通用維護門檻~Hypothetical before/after comparison, not a universal trigger','保持相似雨量比較兩季退水曲線。~Compare seasonal drawdown curves under similar storms.','不控制降雨條件就比較退水時間會誤判堵塞。~Comparing drawdown without storm control can misdiagnose clogging.','兩場雨的退水不同就一定是設備損壞。~Different drawdown in two storms always means damage.')])

C(458,'孔隙堵塞、清掃復原與承載排水協調~Pore clogging, cleaning recovery and structural drainage','environment-urban',
 ['表面孔隙~Surface pores','面層~Surface layer','儲水底層~Storage base','土基~Subgrade','底排~Underdrain','真空清掃~Vacuum cleaning'],['green','swmm'],[
 U('有效透水面積~Effective permeable area','只有連通且未被覆蓋的面積參與入滲；施工封閉、塗層和補丁需單獨標示。~Only connected uncovered area infiltrates; map closures, coatings and patches separately.','Aeff=A(1-fblocked);A=500;fblocked=0.08','500*(1-0.08)',460,'m2','面積帳目，不表示入滲能力均一~Area accounting does not imply uniform infiltration','標出停車格補丁並更新有效面積。~Map parking-space patches and update effective area.','把不透水補丁仍算透水面會高估排水。~Counting impermeable patches overstates drainage.','所有標為透水鋪面的面積都永遠有效。~Every area labeled permeable pavement remains effective forever.'),
 U('現場入滲測試~Field infiltration testing','控制試水範圍、預濕和水頭，才能比較維護前後；水量除面積時間得平均速率。~Control test area, prewetting and head for comparisons; volume over area and time gives average rate.','f=V/(A t);V=0.01 m3;A=0.1 m2;t=0.1 h','0.01/(0.1*0.1)',1,'m/h','局部測試，不能直接代表全場~Local test, not automatically site-wide','在車輪帶與非車輪帶分別重複測試。~Repeat tests in wheel tracks and non-wheel areas.','只挑最乾淨位置會掩蓋高負荷區堵塞。~Testing the cleanest spot hides loaded-area clogging.','一個測點就能代表整個停車場。~One test point represents the entire parking area.'),
 U('儲水底層容量~Base storage capacity','碎石底層用空隙暫存雨水；容量受厚度、有效孔隙與地下水占用影響。~Aggregate-base voids temporarily store rain; thickness, effective porosity and groundwater occupancy constrain capacity.','V=A d n;A=500;d=0.25;n=0.3','500*0.25*0.3',37.5,'m3','未被地下水占用~No groundwater occupancy','提高地下水位使可用厚度減半。~Raise groundwater so available thickness halves.','地下水已淹入底層時仍報全部容量會重複計算。~Reporting full capacity in a flooded base double counts occupied storage.','石層總體積全部都能儲水。~The entire aggregate-base volume stores water.'),
 U('細粒輸入與孔喉~Fine-particle loading and pore throats','細粒可卡在孔喉或深入底層；質量很小也可能優先封住關鍵通路。~Fines lodge in pore throats or migrate downward; small masses can block critical pathways.','annual solids=load area;load=0.2 kg/m2/year;area=500','0.2*500',100,'kg/year','假想平均沉積量~Hypothetical mean deposition','比較入口邊緣與中間區的粒徑分布。~Compare particle-size distributions at edges and the centre.','泥沙由鄰地持續流入會讓清掃效果短暫。~Continuing sediment inflow makes cleaning gains temporary.','只要總泥沙質量不大就不會堵塞。~A small total sediment mass cannot cause clogging.'),
 U('串聯水力阻力~Hydraulic resistance in series','表層、底層與土基共同限制通量；改善表層不保證土基能接收更多水。~Surface, base and subgrade constrain flow together; a cleaner surface does not guarantee greater subgrade acceptance.','Rtot=Rsurface+Rbase+Rsoil;2+1+7','2+1+7',10,'relative resistance','相同截面線性阻力示意~Equal-area linear resistance illustration','將表層阻力減半並比較總阻力變化。~Halve surface resistance and compare total resistance.','忽略最慢土基會把表面恢復誤認全系統恢復。~Ignoring the slow subgrade confuses surface recovery with system recovery.','表面入滲變快就代表所有下層都變快。~Faster surface infiltration makes every lower layer faster.'),
 U('真空清掃復原率~Vacuum-cleaning recovery','復原率應以同一位置、同一測試方法的入滲數據衡量，而不是只看清掃後外觀。~Assess recovery using matched location and method, not appearance alone.','recovery=f_after/f_initial;f_after=0.6;f_initial=0.8','0.6/0.8',0.75,'fraction','初始值為同一測點~Initial value from the same location','比較清掃前0.2、後0.6和初始0.8的差異。~Compare pre-clean0.2, post-clean0.6 and initial0.8.','外觀乾淨但深層細粒仍在，入滲未必全復原。~A clean appearance can leave deeply trapped fines.','清掃一次必定恢復100%初始透水能力。~One cleaning always restores100% of initial permeability.'),
 U('含水與承載~Moisture and bearing performance','透水功能與車載承載需共同設計；持續飽和可能改變土基剛度與變形。~Design infiltration and traffic support together; prolonged saturation can change subgrade stiffness and deformation.','stress=wheel force/contact area;F=20000 N;A=0.04 m2','20000/0.04/1000',500,'kPa','接觸平均應力，非深度應力或承載驗算~Mean contact stress, not subsurface stress or capacity verification','比較乾濕情境下的教學撓度資料。~Compare teaching deflection data in dry and wet cases.','只追求高孔隙而不驗結構會增加車轍風險。~Pursuing porosity without structural checks increases rutting risk.','透水率越高就一定越耐重車。~Higher permeability always gives better heavy-vehicle support.'),
 U('底排失效辨識~Underdrain fault diagnosis','底層水位和出流需聯合量測；高水位可能來自堵塞、土基飽和或下游頂托。~Use base water level and outlet flow together; high level can arise from blockage, saturation or tailwater.','net head=0.35-0.25','0.35-0.25',0.1,'m','兩測點同高程基準~Common elevation datum for both points','同時量測上游水位與出口尾水。~Measure upstream and tailwater levels simultaneously.','只看到無出流就判定土壤吸收全部水量可能錯誤。~No discharge does not prove all water infiltrated into soil.','底排無出水永遠代表入滲成效很好。~No underdrain outflow always means excellent infiltration.'),
 U('污染滯留與去向~Pollutant retention and fate','滯留的金屬與粒子仍留在系統內；清掃廢料與換料需記錄質量和去向。~Retained metals and particles remain in the system; record mass and destination of cleaning residues and replacement media.','retained mass=Min-Mout;Min=12;Mout=3 g','12-3',9,'g/event','事件質量收支~Event mass balance','比較截留量與清掃收集量，追蹤未回收部分。~Compare retention with collected cleaning residue and track the remainder.','把滯留當分解會遺失污染存量管理。~Treating retention as destruction loses inventory control.','孔隙截住污染物就代表它已完全消失。~A trapped pollutant has completely disappeared.'),
 U('分區維護優先序~Prioritize maintenance zones','用入滲衰減、積水頻率和泥沙來源排序，而不是全場固定同頻率清掃。~Prioritize infiltration decline, ponding frequency and sediment sources rather than uniform cleaning schedules.','risk score=frequency*consequence;3*4','3*4',12,'ordinal score','僅相對排序，序位分數不是失效機率~Relative ranking only; ordinal scores are not failure probabilities','對三個分區排序並說明資料不足處。~Rank three zones and note data gaps.','只依面積大者優先可能漏掉關鍵出入口。~Area-only priority can miss critical entrances.','序位風險12代表12%的失效機率。~An ordinal risk score of12 means12% failure probability.')])

C(459,'街樹根域、雨水與人行空間協調~Coordinate root volume, stormwater and pedestrian space','environment-urban',
 ['街道匯流~Street runoff','路緣開口~Curb opening','樹穴~Tree pit','結構土與根域~Structural soil and roots','通氣底排~Aeration and drainage','人行界面~Pedestrian interface'],['green','swmm'],[
 U('樹穴集水分區~Tree-pit catchment','路緣高度與坡向決定哪一段街道供水；樹冠面積不是集水面積。~Curb height and slopes define the supplying street reach; canopy area is not catchment area.','V=C P A;C=0.85;P=0.02;A=150','0.85*0.02*150',2.55,'m3','單場逕流~Single-storm runoff','描繪相鄰兩樹穴集水界線。~Map catchment boundaries between adjacent pits.','集水分配不均會一株過濕另一株缺水。~Unequal capture can waterlog one tree and dry another.','樹冠越大就必定截住更多路面逕流。~A larger canopy necessarily captures more road runoff.'),
 U('根域有效土量~Effective rooting volume','根可利用的連通土量受基礎、管線與壓實限制；名目開挖體積需扣除障礙。~Connected rooting soil is limited by foundations, utilities and compaction; subtract obstructions from excavation volume.','Vroot=Vgross-Vblocked;12-3','12-3',9,'m3','幾何估計，不是樹種需求值~Geometric estimate, not a species-specific requirement','將地下管線畫入剖面並更新連通土量。~Add utilities to the section and update connected soil volume.','把不連通土穴相加會高估可用根域。~Adding isolated pockets overstates usable root space.','開挖總體積全部都能被根系利用。~Roots can use the whole excavation volume.'),
 U('根域孔隙與含氣量~Root-zone pores and aeration','土壤水分和空氣共享孔隙；長期滿水會降低氧擴散。~Water and air share pores; sustained saturation limits oxygen diffusion.','air porosity=n-theta;n=0.45;theta=0.35','0.45-0.35',0.1,'m3/m3','均勻介質的體積分率~Volume fractions in a uniform medium','提高含水率並比較含氣孔隙。~Raise water content and compare air-filled porosity.','將最大蓄水當唯一目標可能使根域缺氧。~Maximizing storage alone can deprive roots of oxygen.','樹根區越濕永遠越有利。~A wetter root zone is always better.'),
 U('沉砂與入口保護~Sediment and inlet protection','路緣開口可帶入砂、垃圾與冬季鹽分；可維護的前區減少根域埋塞。~Curb openings admit sediment, litter and salts; a maintainable forezone protects the root medium.','sediment=V C;V=2.55;C=0.1 kg/m3','2.55*0.1',0.255,'kg/event','平均事件濃度假設~Assumed event-mean concentration','檢查入口與樹幹基部的沉積分布。~Inspect deposition at the inlet and trunk base.','沉積抬高後會把後續逕流導離樹穴。~Accumulated sediment can divert later runoff away.','入口沉砂不會影響以後的捕水率。~Inlet sediment never affects later capture.'),
 U('地表蓄水與根頸~Surface storage and root collar','蓄水高程需與根頸、人行路面及溢流配合；幾何容量不等於可任意淹水深度。~Coordinate storage elevation with root collar, pavement and overflow; geometric capacity is not permission for arbitrary flooding.','V=A h;A=4 m2;h=0.15 m','4*0.15',0.6,'m3','簡化平底樹穴~Simplified flat-bottom pit','在剖面標示根頸與最高模擬水位。~Mark root collar and maximum simulated water level in section.','蓄水邊緣過高可能使根頸長期淹水。~An excessively high storage rim can submerge the root collar.','所有樹種都可長期淹到樹幹基部。~Every tree species tolerates permanent trunk-base flooding.'),
 U('蒸散與灌溉缺口~Evapotranspiration and irrigation deficit','雨水補給與蒸散不一定同季節；需以水量帳目估乾期缺口。~Rain supply and evapotranspiration may peak in different seasons; use a water budget for dry-period deficit.','deficit=demand-captured;0.30-0.18','0.30-0.18',0.12,'m3/day','假想日均需求，非灌溉處方~Hypothetical daily need, not an irrigation prescription','用一週乾天資料檢查儲水是否耗盡。~Use a dry week to check depletion of stored water.','全年雨量充足不代表乾季每一天有足夠水。~Adequate annual rain does not ensure daily dry-season supply.','年雨量大就永遠不需考慮乾季缺水。~High annual rainfall eliminates dry-season water shortage.'),
 U('結構土與壓實取捨~Structural soil and compaction trade-offs','人行承載需要穩定骨架，根域需要孔隙與水氣；兩種要求須共同驗證。~Pavement needs a stable skeleton while roots need pore space and water-air exchange; validate both.','bulk density=M/V;M=1600 kg;V=1 m3','1600/1',1600,'kg/m3','僅表觀密度，無法單獨判定根域合格~Bulk density alone does not establish rooting suitability','同時比較承載試驗與入滲、含氣孔隙。~Compare bearing tests with infiltration and air-filled porosity.','只提高壓實度可能損害根系與入滲。~Increasing compaction alone can impair roots and infiltration.','路面承載合格就代表根系條件也合格。~Acceptable pavement support proves acceptable root conditions.'),
 U('鹽分累積~Salt accumulation','蒸散移走水卻不等量移走鹽，根域可能濃縮；需檢查排水與鹽分輸入。~Evapotranspiration removes water without equivalent salt removal, potentially concentrating the root zone.','Cfinal=M/V;M=0.12 kg;V=0.3 m3','0.12/0.3',0.4,'kg/m3','完全混合且無吸附的示例~Completely mixed example without sorption','將蒸散造成的水量減少列入鹽收支。~Include evapotranspiration water loss in the salt balance.','只測雨水低鹽可能漏掉路面與介質鹽源。~Low-salt rain measurements miss road and soil salt sources.','蒸散會按照相同比例移走水與鹽。~Evapotranspiration removes water and salt in equal proportion.'),
 U('樹根與地下管線~Roots and buried utilities','以管線位置、可達維修區與根域連通性協調配置，避免把根系直接視為障礙物。~Coordinate utilities, maintenance access and connected rooting space rather than treating roots merely as obstructions.','clear fraction=unobstructed width/total width;1.5/2','1.5/2',0.75,'fraction','示意幾何，不是法定淨距~Illustrative geometry, not a statutory clearance','比較移動管線與改變樹穴的兩個剖面方案。~Compare sections with relocated utilities or redesigned pits.','施工後才發現管線會迫使切斷根域連通。~Late utility discovery can sever planned soil continuity.','地下管線位置對樹穴設計沒有影響。~Buried utilities do not affect tree-pit design.'),
 U('生長與水工共同驗收~Joint vegetation and hydraulic review','樹勢、入滲與人行安全需分別追蹤，單一綠覆率不能代表整體功能。~Track tree condition, infiltration and pedestrian safety separately; canopy cover alone is insufficient.','inspection completion=14/16','14/16',0.875,'fraction','巡查清單覆蓋~Inspection checklist coverage','將缺水、積水、根浮與入口堵塞分開記錄。~Record drought stress, ponding, root heave and inlet blockage separately.','以樹葉茂密掩蓋路面隆起會漏掉使用風險。~Dense foliage can hide pavement heave concerns.','只要樹葉茂盛，所有工程功能就都正常。~Abundant leaves prove every engineering function works.')])

C(460,'社區入滲的地層、地下水與事件調蓄~Stratigraphy, groundwater and event storage for community infiltration','environment-urban',
 ['集水區~Catchment','污染篩查~Contamination screening','前處理~Pretreatment','滲透溝~Infiltration trench','觀測井~Observation well','溢流通路~Overflow route'],['green','swmm'],[
 U('集水組成與逕流~Catchment composition and runoff','屋頂、道路和草地具有不同截留與污染來源，先分區再合成。~Roofs, roads and lawns have different interception and pollutant sources; combine only after separate accounting.','effective area=sum(C A);0.9*600+0.3*400','0.9*600+0.3*400',660,'m2','固定事件係數的教學估算~Teaching estimate with fixed event coefficients','把100m2草地改成鋪面並重算有效面積。~Convert100m2 of lawn to pavement and recalculate effective area.','土地使用變更而不更新集水資料會低估水量。~Unupdated land-use changes understate runoff.','社區面積不變就代表逕流永遠不變。~An unchanged community area means unchanged runoff.'),
 U('入滲量與儲存需求~Infiltration and storage demand','雨期進流與可入滲量差值形成儲存需求；不能只比較日總量。~The difference between inflow and infiltration during rain creates storage demand; daily totals alone are insufficient.','storage=Vin-f A t;Vin=30;f=0.01;A=100;t=2 h','30-0.01*100*2',28,'m3','均勻入滲、單場雨~Uniform infiltration during one storm','比較同總雨量的短強雨和長弱雨。~Compare short intense and long weak storms with equal totals.','日入滲能力足夠仍可能在短強雨溢流。~Adequate daily capacity can still overflow in a short intense storm.','日總雨量小於日入滲量就絕不會溢流。~Daily rain below daily infiltration guarantees no overflow.'),
 U('地層調查與最慢層~Stratigraphy and the limiting layer','薄低滲層可能支配垂向排水；需把孔隙、滲透與污染背景放在同一剖面。~A thin low-permeability layer may control vertical drainage; map pores, conductivity and contamination on one section.','R=sum(L/K);0.2/0.02+0.1/0.001','0.2/0.02+0.1/0.001',110,'h','一維飽和串聯阻力~One-dimensional saturated series resistance','移除或加厚低滲層，比較等效阻力。~Remove or thicken the low-permeability layer and compare resistance.','只做淺表試驗會漏掉深處限制。~Shallow testing misses deeper constraints.','表層土壤可代表所有深度地層。~Surface soil represents all depths.'),
 U('地下水距離與水丘~Groundwater separation and mounding','入滲會改變地下水位；原始距離不等於暴雨後的有效距離。~Infiltration can raise groundwater; initial separation differs from post-storm separation.','remaining separation=initial-rise;2.0-0.6','2.0-0.6',1.4,'m','假想已計算水丘高度，不是通用允收距離~Assumed modeled mound, not a universal acceptance distance','比較乾季與濕季地下水位並記錄基準高程。~Compare dry- and wet-season levels with a common datum.','用最低季節水位會高估安全間距。~Using the seasonal minimum overstates separation.','地下水位在入滲過程中永遠不變。~Groundwater level never changes during infiltration.'),
 U('前處理與堵塞負荷~Pretreatment and clogging load','沉砂或植生前處理降低顆粒入滲負荷，但需有可清理入口。~Sedimentation or vegetated pretreatment reduces particle loading and needs accessible cleaning.','remaining solids=M(1-eta);M=20 kg;eta=0.7','20*(1-0.7)',6,'kg/event','固定去除率示例~Fixed-removal illustration','把前池去除率由0.7降到0.4，估入滲床負荷。~Reduce forebay removal from0.7 to0.4 and estimate bed loading.','前處理滿載會加速入滲面堵塞。~A full pretreatment unit accelerates infiltration-surface clogging.','前處理去除率不需隨維護狀態改變。~Pretreatment removal is independent of maintenance.'),
 U('入滲溝空隙容量~Trench void storage','碎石與模組儲水的有效孔隙不同，設計帳目需使用實際可用水體積。~Aggregate and modular storage have different usable porosity; account for actual water volume.','V=L W D n;L=20;W=2;D=1;n=0.35','20*2*1*0.35',14,'m3','未扣管件與既有水量~Excludes fittings and antecedent water occupancy','比較相同開挖體積兩種孔隙率。~Compare two porosities at equal excavation volume.','把總挖方當儲水量會放大容量。~Using excavation volume exaggerates storage.','碎石溝體積等於可儲水體積。~Aggregate-trench volume equals water-storage volume.'),
 U('污染場址與入滲限制~Contaminated sites and infiltration limits','入滲可能推動既有污染遷移；先建立污染概念模型，再決定是否適合入滲。~Infiltration may mobilize existing contamination; develop a conceptual site model before deciding suitability.','travel time=L/v;L=3 m;v=0.05 m/day','3/0.05',60,'day','不含吸附和降解的平流示意~Advection illustration without sorption or decay','比較清潔回填與污染層兩種流路。~Compare flow paths through clean fill and a contaminated layer.','把雨水乾淨當成地下環境也乾淨會漏掉污染源。~Clean rain does not imply clean subsurface conditions.','任何棕地都適合直接增加入滲。~Every brownfield is suitable for increased infiltration.'),
 U('溢流路線與串聯系統~Overflow routes and linked systems','設施滿水時，溢流應導向可承受的路徑；多設施串接需要考慮同時滿載。~When storage fills, overflow needs an appropriate route; linked systems can fill simultaneously.','residual=Vstorm-Vstore-Vinf;50-28-10','50-28-10',12,'m3','事件桶模型，未含下游回水~Event bucket model without downstream backwater','模擬兩座設施同時滿水，追蹤最後溢流。~Fill two facilities simultaneously and trace final overflow.','只假設下一座永遠有空間會低估總風險。~Assuming downstream storage is always empty understates risk.','串接越多座就不可能發生溢流。~More facilities in series make overflow impossible.'),
 U('觀測井與退水診斷~Observation wells and drawdown diagnosis','內部水位能看出表面看不到的飽和與底部排水狀態。~Internal water levels reveal saturation and drainage hidden below the surface.','drawdown rate=(h1-h2)/dt;(0.8-0.2)/12','(0.8-0.2)/12',0.05,'m/h','兩點平均下降速率~Two-point mean drawdown rate','以連續水位比較線性、指數與尾端緩慢退水。~Compare linear, exponential and slow-tail drawdown shapes.','表面無水就停止觀測可能錯過底層長期飽和。~Stopping when the surface dries misses persistent lower saturation.','地表乾燥必定代表入滲溝已完全排空。~A dry surface means the trench is completely empty.'),
 U('多目標維護與居民介面~Maintenance and community interface','入滲、環境品質與公共使用需共同驗收；維護資料應能讓居民理解預期功能。~Review infiltration, environmental quality and public use together; maintenance records should explain intended functions.','maintenance coverage=completed tasks/planned;9/12','9/12',0.75,'fraction','工作完成度不代表所有性能達標~Task completion does not prove all performance targets','把淤積、積水與垃圾各自配對責任人及證據。~Assign owners and evidence separately for sediment, ponding and litter.','只完成清掃而不量退水，無法驗證功能恢復。~Cleaning without drawdown measurements cannot verify recovery.','維護工單勾選完成即可取代性能量測。~A completed work order replaces performance measurement.')])

C(461,'鋪面能量收支與行人熱曝露~Pavement energy balance and pedestrian heat exposure','environment-urban',
 ['日射~Solar radiation','表面光學~Surface optics','熱儲存~Heat storage','對流與輻射~Convection and radiation','蒸發~Evaporation','行人量測~Pedestrian measurements'],['cool','coolreport'],[
 U('表面與氣溫指標~Surface and air-temperature measures','表面熱島與空氣熱島量測高度、時間和物理量不同；必須先定義比較對象。~Surface and air heat-island metrics differ in height, timing and quantity; define the comparison first.','surface contrast=Ts_urban-Ts_reference;48-35','48-35',13,'K','同時同天候表面溫差~Simultaneous surface-temperature contrast under equal weather','並列地表與遮陽氣溫，避免混用兩種溫差。~Plot surface and shielded air temperature separately.','紅外影像顯示降溫不能直接當成人體氣溫降幅。~Infrared surface cooling is not directly an air-temperature reduction.','表面降低10度就代表行人氣溫也降低10度。~A10-degree surface reduction means a10-degree pedestrian air reduction.'),
 U('短波反射與吸收~Shortwave reflection and absorption','反照率增加可降低鋪面吸收，但增加的反射光可能照到人或牆面。~Higher albedo reduces pavement absorption but may direct more reflected radiation toward people or walls.','Qabs=(1-alpha)G;alpha=0.35;G=800 W/m2','(1-0.35)*800',520,'W/m2','忽略透射的不透明表面~Opaque surface with negligible transmission','把反照率由0.15改為0.35，核對吸收差值。~Change albedo from0.15 to0.35 and check absorbed-flux difference.','只量表面溫度可能漏掉行人反射短波負荷。~Surface temperature alone misses reflected shortwave load on pedestrians.','反照率提高必定降低所有方向的輻射負荷。~Higher albedo reduces radiation load in every direction.'),
 U('熱容量與升溫~Heat capacity and warming','厚度、密度與比熱控制短時間儲熱；相同熱通量不代表相同升溫。~Thickness, density and heat capacity control transient storage; equal flux does not imply equal warming.','DeltaT=q t/(rho c d);q=200;t=3600;rho=2200;c=900;d=0.1','200*3600/(2200*900*0.1)',3.636363636,'K','忽略散熱、均溫薄層近似~Uniform-layer approximation neglecting heat losses','比較厚度加倍與比熱加倍的結果。~Compare doubled thickness with doubled specific heat.','把吸收通量全部長期存入薄層會造成不實高溫。~Storing all absorbed energy indefinitely in a thin layer produces unrealistic temperatures.','熱容量對白天升溫完全沒有影響。~Heat capacity has no effect on daytime warming.'),
 U('對流換熱~Convective heat transfer','風速和表面形態會改變對流係數；係數不是所有街谷共用常數。~Wind and surface geometry change convection; the coefficient is not universal across streets.','q=h(Ts-Ta);h=12;Ts=45;Ta=32','12*(45-32)',156,'W/m2','假想平均換熱係數~Hypothetical mean coefficient','在相同日射下比較有風與無風時段。~Compare windy and calm periods at similar solar input.','把風速改變造成的降溫全歸因塗層會錯判效益。~Attributing wind-driven cooling entirely to coating misjudges benefit.','同一塗層在任何風速下表現完全相同。~A coating performs identically at every wind speed.'),
 U('長波放射與天空~Longwave exchange with the sky','長波放射依絕對溫度四次方與放射率計算，天空有效溫度亦影響夜間散熱。~Longwave emission depends on the fourth power of absolute temperature and emissivity; effective sky temperature affects night cooling.','q=epsilon sigma(Ts^4-Tsky^4);eps=0.9;sigma=5.67e-8;Ts=315K;Tsky=290K','0.9*5.67e-8*(315**4-290**4)',141.495505594,'W/m2','以有效天空溫度代表長波環境~Effective sky temperature represents the longwave environment','以開闊天空與遮蔽街谷比較可見天空比例。~Compare sky-view fractions in open and shaded canyons.','以攝氏代入四次方公式會得到錯誤熱通量。~Using Celsius in the fourth-power formula gives incorrect flux.','史蒂芬—波茲曼式可直接使用攝氏溫度。~Stefan-Boltzmann calculations can directly use Celsius.'),
 U('蒸發冷卻用水~Evaporative cooling and water','蒸發移走潛熱但需可用水與質傳；供水不足時效益會衰退。~Evaporation removes latent heat but requires available water and mass transfer; cooling fades when water is exhausted.','q=m_dot L;mdot=0.00005 kg/m2/s;L=2450000 J/kg','0.00005*2450000',122.5,'W/m2','假想穩態蒸發率~Hypothetical steady evaporation rate','同步量測失水量與表面溫度。~Measure water loss and surface temperature together.','僅記灑水後瞬間溫度會高估全天效益。~A temperature immediately after watering overstates all-day benefit.','蒸發冷卻完全不需消耗水。~Evaporative cooling consumes no water.'),
 U('夜間釋熱~Nighttime heat release','白天吸收的能量可能延後釋放；材料降溫評估要包含日夜週期。~Daytime storage may be released later; assess a day-night cycle.','mean nocturnal flux=stored energy/night duration;3.6e6 J/m2/36000s','3.6e6/36000',100,'W/m2','假設整段均勻釋放~Assumes uniform release over the interval','比較日間峰值與夜間累積釋熱。~Compare daytime peaks with accumulated night release.','只評午後一小時會漏掉夜間熱負荷。~Evaluating one afternoon hour misses nighttime load.','白天表面較冷就一定代表夜間釋熱較少。~A cooler daytime surface necessarily releases less heat at night.'),
 U('人體輻射視角~Human radiation view factors','行人接收天空、路面與牆面的綜合輻射，表面改善不能單獨代表熱舒適。~Pedestrians receive radiation from sky, pavement and walls; one surface does not define comfort.','weighted added shortwave=F alpha G;F=0.2;DeltaAlpha=0.2;G=800','0.2*0.2*800',32,'W/m2','簡化幾何加權，不是人體舒適指標~Simplified geometric weighting, not a comfort index','比較遮陽下與無遮陽的輻射量測。~Compare radiative measurements in shade and sun.','高反射鋪面可能降低表面溫度卻增加局部反射曝露。~Reflective pavement may cool its surface while increasing local reflected exposure.','只看路面溫度就能算出完整人體熱舒適。~Pavement temperature alone determines complete thermal comfort.'),
 U('老化、髒污與反照率~Aging, soiling and albedo','表面磨耗與髒污改變反射率；初期性能需要長期追蹤。~Wear and soiling alter reflectance; track initial performance over time.','absorbed increase=(alpha_new-alpha_old)G;(0.35-0.25)*800','(0.35-0.25)*800',80,'W/m2','固定日射的反射變化比較~Reflectance comparison at fixed solar input','在相同量測角度比較清洗前後反照率。~Compare albedo before/after cleaning at matched geometry.','引用新材反照率代表多年使用會高估效益。~Using new-material albedo for aged pavement overstates benefit.','鋪面反照率在全壽命期間都不變。~Pavement albedo remains constant throughout its life.'),
 U('配對現地試驗~Matched field comparison','比較區需控制日射、風、遮蔭和交通；用配對差值降低天候混淆。~Control sun, wind, shade and traffic; paired differences reduce weather confounding.','difference-in-differences=(after_test-before_test)-(after_control-before_control);(40-46)-(44-48)','(40-46)-(44-48)',-2,'K','示例差異中的差異，未含統計顯著性~Illustrative difference-in-differences without significance inference','先定義比較時段與排除維護事件規則。~Define comparison periods and maintenance exclusions in advance.','不同日天候直接比較會把氣象差異當材料效益。~Comparing different-weather days confuses meteorology with material benefit.','任何兩天的最高溫都能直接比較材料效果。~Any two daily maxima directly compare material effects.')])

C(462,'城市幾何、風場邊界與可驗證CFD~Urban geometry, wind boundaries and verifiable CFD','environment-urban',
 ['地形與建物~Terrain and buildings','來流剖面~Inflow profile','網格~Mesh','流場求解~Flow solution','行人測點~Pedestrian probes','風洞比對~Wind-tunnel comparison'],['ava','avaresearch'],[
 U('風向與暴露情境~Wind directions and exposure cases','城市通風需要多風向與代表氣象頻率；單一風向不能代表全年。~Urban ventilation requires multiple directions and representative frequencies; one direction does not represent a year.','weighted speed=sum(p U);0.5*1+0.3*2+0.2*0.5','0.5*1+0.3*2+0.2*0.5',1.2,'m/s','假想三風向權重，非風舒適標準~Hypothetical three-direction weights, not a comfort standard','改變風向權重，觀察平均風速與低風區。~Change directional weights and examine mean speed and stagnant areas.','選有利風向可能掩蓋常見弱通風情境。~Choosing a favorable direction hides frequent weak-ventilation cases.','一個風向模擬即可證明全年通風良好。~One simulated wind direction proves good year-round ventilation.'),
 U('相對風速~Velocity ratio','以共同參考高度的風速歸一化，才能比較建物方案而不混入來流強弱。~Normalize by a common reference-height speed to compare schemes without confounding inflow strength.','VR=Uped/Uref;Uped=1.2;Uref=4','1.2/4',0.3,'ratio','相同參考高度與來流定義~Same reference height and inflow definition','把參考風速改變，檢查不同方案是否使用一致分母。~Change reference speed and check consistent denominators across schemes.','每個方案選不同參考點會製造假改善。~Different reference points create artificial improvements.','不同參考高度的VR可不經說明直接比較。~VRs using different reference heights can be compared without qualification.'),
 U('街谷幾何~Street-canyon geometry','高寬比影響回流與天空開口，但相同高寬比仍可能有不同沿街通道和熱浮力。~Height-width ratio affects recirculation and sky opening, but equal ratios can have different along-street channels and buoyancy.','aspect ratio=H/W;H=30;W=20','30/20',1.5,'ratio','幾何指標不是完整流動解~Geometric indicator, not a full flow solution','比較同高寬比但不同街道方向的配置。~Compare equal aspect ratios with different street orientations.','僅用H/W預測所有風速會忽略三維端部效應。~Using H/W alone misses three-dimensional end effects.','高寬比相同的街谷風場必定完全相同。~Equal aspect ratios guarantee identical canyon wind fields.'),
 U('連續方程與通量~Continuity and flux','不可壓流的進出質量應平衡；殘差下降仍需檢查全域通量。~Incompressible inflow and outflow mass must balance; residual reduction still requires a global flux check.','relative imbalance=abs(Qin-Qout)/Qin;100,99','abs(100-99)/100',0.01,'fraction','全域流量收支示例~Illustrative global volume balance','列出所有開放邊界通量並計總和。~Tabulate fluxes on every open boundary and sum them.','只看求解器殘差小可能漏掉邊界設定錯誤。~Small solver residuals can hide incorrect boundaries.','殘差小就不必再檢查質量守恆。~Small residuals make mass-conservation checks unnecessary.'),
 U('來流剖面與地表粗糙~Inflow profile and roughness','平均速度與紊流邊界需和地表粗糙處理一致，不一致會在到達建物前改變流場。~Mean velocity and turbulence boundaries must match roughness treatment or the flow changes before reaching buildings.','log-profile ratio=ln(z2/z0)/ln(z1/z0);z2=20;z1=10;z0=0.5','log(20/0.5)/log(10/0.5)',1.231378213,'ratio','中性、對數層的教學近似~Teaching approximation in a neutral logarithmic layer','用空場模型檢查剖面是否沿程保持。~Use an empty-domain model to check profile preservation.','入口給對數剖面但地面用不相容壁函數會造成假剪切。~An incompatible wall treatment creates artificial shear.','入口剖面一旦指定就不會受地面模型影響。~A specified inlet profile is unaffected by the ground model.'),
 U('網格敏感度~Mesh sensitivity','細化需檢查關鍵測點與流動特徵，不只增加總格數；尖角與狹縫要有解析度。~Refine key probes and flow features, not merely total cell count; resolve corners and narrow gaps.','relative change=abs(Ufine-Umed)/Ufine;1.02,1.00','abs(1.02-1.00)/1.02',0.019607843,'fraction','兩網格比較，不等於正式離散誤差估計~Two-grid comparison, not a formal discretization-error estimate','在三層網格比較同一行人測點。~Compare the same pedestrian probe across three meshes.','只在高風處檢查可能漏掉低風回流區不收斂。~Checking only fast zones misses unresolved recirculation.','網格數多就自動保證結果準確。~Many cells automatically guarantee accuracy.'),
 U('雷諾數與縮尺~Reynolds number and scale','風洞與數值模型需評估相似條件；幾何縮尺並不自動維持雷諾數。~Assess similarity for wind-tunnel and numerical models; geometric scaling does not automatically preserve Reynolds number.','Re=U L/nu;U=2;L=20;nu=1.5e-5','2*20/1.5e-5',2666666.6667,'dimensionless','單一特徵長度的量級估算~Order-of-magnitude estimate using one characteristic length','把模型長度縮小100倍並比較Re。~Reduce model length100-fold and compare Re.','把縮尺速度不變視為所有物理相似會漏掉尺度效應。~Unchanged model speed does not preserve all physics.','任何幾何縮尺都保持所有無因次數不變。~Any geometric scale change preserves every dimensionless number.'),
 U('污染稀釋與通風~Pollutant dilution and ventilation','較大平均風速不必然降低每一點濃度，污染源位置與回流決定暴露。~Higher average speed does not necessarily lower concentration everywhere; source placement and recirculation govern exposure.','well-mixed concentration=S/Q;S=20 mg/s;Q=100 m3/s','20/100',0.2,'mg/m3','完全混合箱模型，非街谷CFD結果~Well-mixed box model, not a street-canyon CFD result','移動污染源至背風面，觀察局部濃度差異。~Move a source to the leeward side and inspect local concentration.','用箱模型平均濃度代替行人局部峰值會低估曝露。~A box average can understate local pedestrian peaks.','風速平均增加就代表所有測點污染濃度都下降。~Higher mean wind speed means lower pollution at every point.'),
 U('方案比較與開口~Scheme comparison and openings','開口、退縮與架空層改變通道，但需確認改善是否把不利風移到其他區域。~Openings, setbacks and void decks redirect flow; check whether improvement shifts adverse wind elsewhere.','improvement=(VRnew-VRold)/VRold;0.36,0.30','(0.36-0.30)/0.30',0.2,'fraction','同參考風速的局部變化~Local change under the same reference speed','畫出全區差值圖而非只報最佳測點。~Map differences over the whole area rather than the best probe.','單點改善可能伴隨另一處停滯或加速。~One improved probe can accompany stagnation or acceleration elsewhere.','最佳測點改善就等於全區都改善。~Improvement at the best point means improvement everywhere.'),
 U('實測驗證與模型限制~Measurement validation and limits','以風洞或現地資料檢查可觀測量並保留模型差異；計算流場不是經校正數位孿生的自動證明。~Validate observables against wind-tunnel or field data and retain discrepancies; computed flow alone does not establish a calibrated digital twin.','MAE=(abs(1.1-1)+abs(0.7-0.8)+abs(1.4-1.2))/3','(abs(1.1-1)+abs(0.7-0.8)+abs(1.4-1.2))/3',0.133333333,'m/s','三個假想配對測點~Three hypothetical paired probes','將風向誤差和速度誤差分開報告。~Report directional and speed errors separately.','只展示流線動畫而無量測比較會隱藏模型不確定度。~Streamline animation without measured comparison hides uncertainty.','流場動畫寫實就代表預測已被驗證。~Realistic flow animation means the prediction is validated.')])

C(463,'冷量傳輸、壓降與低溫差診斷~Cooling transfer, pressure loss and low-temperature-difference diagnosis','environment-urban',
 ['中央冷站~Central chiller plant','供水主幹~Supply main','用戶換熱器~Customer exchanger','控制閥~Control valve','回水主幹~Return main','蓄冷~Thermal storage'],['district','heat'],[
 U('冷量與水流~Cooling duty and flow','冷量由質量流率、比熱與供回水溫差決定；流量不能獨立代表服務量。~Cooling duty is mass flow times heat capacity and temperature difference; flow alone does not measure service.','Qcool=m cp DeltaT;m=20 kg/s;cp=4.18 kJ/kg/K;DeltaT=6K','20*4.18*6',501.6,'kW','水的定比熱近似~Constant water heat-capacity approximation','改變溫差並保持流量，觀察冷量。~Vary temperature difference at fixed flow and observe duty.','高流量低溫差可能仍傳送不足冷量。~High flow with low temperature difference can still deliver insufficient cooling.','供水流量越大就一定提供越多有效冷量。~Higher flow always delivers more useful cooling.'),
 U('管徑與流速~Pipe diameter and velocity','流速影響壓降、噪音和控制；管徑以截面平方影響速度。~Velocity affects pressure drop, noise and control; diameter changes area quadratically.','v=4Q/(pi D^2);Q=0.02 m3/s;D=0.15m','4*0.02/(pi*0.15**2)',1.131768484,'m/s','單圓管滿流~Full flow in one circular pipe','管徑減少10%，比較流速增加幅度。~Reduce diameter ten percent and compare velocity increase.','內徑與公稱管徑混用會偏移壓降估算。~Mixing internal and nominal diameters biases pressure loss.','管徑減半只會讓流速加倍。~Halving diameter merely doubles velocity.'),
 U('沿程壓降~Distributed pressure loss','達西摩擦因數須與雷諾數和粗糙度相容；局部元件損失另列。~Match Darcy friction factor to Reynolds number and roughness; list local losses separately.','DeltaP=f(L/D)rho v^2/2;f=0.02;L=200;D=0.15;rho=1000;v=1.2','0.02*(200/0.15)*1000*1.2**2/2',19200,'Pa','假想固定摩擦因數~Hypothetical fixed Darcy factor','將流速增加20%，重算平方效應。~Increase velocity20% and recalculate the square-law effect.','漏算換熱器和閥損會低估泵揚程。~Omitting exchanger and valve losses understates pump head.','管路壓降與流速永遠成一次正比。~Pipe pressure drop is always linearly proportional to speed.'),
 U('泵浦與電力~Pumping and electricity','電功率是液壓功除效率；變頻節能需看系統曲線與最低壓差。~Electrical power is hydraulic power divided by efficiency; variable-speed savings depend on system curves and minimum differential pressure.','P=DeltaP Q/eta;DeltaP=60000;Q=0.02;eta=0.75','60000*0.02/0.75/1000',1.6,'kW','不含馬達外其他輔機~Excludes other auxiliaries','同步記錄流量、壓差與耗電檢查效率。~Record flow, pressure and electricity to check efficiency.','用名牌最高效率代表所有負載會高估節能。~Using nameplate peak efficiency at every load overstates savings.','泵浦效率在所有轉速都固定不變。~Pump efficiency is constant at all speeds.'),
 U('低溫差症候群~Low-delta-T syndrome','回水溫差過小迫使相同冷量使用更多水，增加網路流量與泵功。~A small return temperature difference requires more water for equal duty, increasing network flow and pumping.','m=Q/(cp DeltaT);Q=500;cp=4.18;DeltaT=3','500/(4.18*3)',39.87240829,'kg/s','固定冷量與定比熱~Fixed duty and heat capacity','比較DeltaT為3K與6K的流量需求。~Compare required flow at3K and6K.','閥常開或換熱器控制不良可能造成旁通混水。~Stuck-open valves or poor exchanger control can cause bypass mixing.','回水越接近供水溫度就代表系統越有效率。~A return temperature closer to supply means higher efficiency.'),
 U('換熱器溫差推動~Heat-exchanger driving difference','換熱器傳熱以面積、總傳熱係數和對數平均溫差連結；污垢降低有效UA。~Heat transfer links area, overall coefficient and logarithmic mean difference; fouling lowers effective UA.','LMTD=(DeltaT1-DeltaT2)/ln(DeltaT1/DeltaT2);8,4','(8-4)/log(8/4)',5.770780164,'K','逆流理想化且無相變~Ideal counterflow without phase change','比較清潔與污損時所需面積或流量。~Compare clean/fouled area or flow requirements.','只增加流量可能無法補救受限UA。~More flow may not compensate for limited UA.','換熱器溫差可直接用任意兩端算術平均代替。~Any arithmetic average of endpoint differences replaces LMTD.'),
 U('管線熱增益~Heat gain in pipes','保溫和埋地環境決定沿線冷量損失；供回兩管需個別記錄。~Insulation and surroundings govern heat gain; account for supply and return separately.','heat gain=Uprime L DeltaT;Uprime=0.4 W/m/K;L=500;DeltaT=20','0.4*500*20/1000',4,'kW','線性穩態熱傳估算~Linear steady heat-transfer estimate','比較保溫受潮前後的Uprime。~Compare line conductance before and after insulation wetting.','保溫受潮可能同時增加熱損與腐蝕風險。~Wet insulation can increase both thermal loss and corrosion concerns.','地下管線完全不會與環境交換熱。~Buried pipes exchange no heat with the environment.'),
 U('蓄冷容量與削峰~Thermal-storage capacity and peak shaving','水蓄冷以有效溫差儲能；混合破壞分層會降低可用容量。~Water storage holds energy through useful temperature difference; mixing destroys stratification and reduces usable capacity.','E=rho V cp DeltaT/3600;rho=1000;V=100;cp=4.18;DeltaT=6','1000*100*4.18*6/3600',696.6666667,'kWh','理想水槽顯熱，未扣混合與損失~Ideal sensible storage before mixing and losses','提高無效混合比例並比較可用削峰時數。~Increase mixing loss and compare usable peak-shaving hours.','總水量乘最大溫差會高估已混合水槽容量。~Total volume times maximum deltaT overstates a mixed tank.','任何混合狀態下儲槽容量都一樣。~Storage capacity is independent of mixing state.'),
 U('多用戶同時率~Demand coincidence','個別最大冷量不一定同時出現；以同步時序估計網路峰值。~Individual maxima need not coincide; use synchronized series for network peak.','coincidence=network peak/sum individual peaks;800/1000','800/1000',0.8,'fraction','假想同期間量測~Hypothetical measurements over the same period','比較相加最大值與逐時加總後最大值。~Compare summed individual maxima with the maximum hourly sum.','用月帳單平均值估尖峰可能低估設備需求。~Monthly-average billing data can understate peak requirements.','所有用戶最大負載一定同時發生。~All customer maxima occur simultaneously.'),
 U('熱量計誤差與交接~Heat-meter uncertainty and handover','流量與供回溫差共同決定計費冷量；小溫差時溫度偏差尤其重要。~Flow and temperature difference jointly determine metered cooling; temperature bias matters especially at low deltaT.','relative DeltaT error=0.2/3','0.2/3',0.066666667,'fraction','固定差溫偏差的示例~Example of fixed differential-temperature bias','交換兩支溫度探頭位置，檢查偏差方向。~Swap temperature probes and check bias direction.','未配對校正探頭會把量測偏差當網路損失。~Unmatched probe calibration can look like network loss.','只校正流量計就能保證冷量計完全準確。~Calibrating flow alone guarantees accurate heat metering.')])

C(464,'污水熱源、熱泵循環與系統能效~Wastewater heat sources, heat-pump cycles and system efficiency','environment-urban',
 ['污水側~Wastewater side','防污換熱器~Fouling-resistant exchanger','二次迴路~Secondary loop','熱泵~Heat pump','用熱端~Heat demand','監控~Monitoring'],['heat','recovery'],[
 U('熱源時序與需求~Source timing and demand','污水流量、溫度與用熱需求需同步；平均有熱不代表尖峰時可用。~Synchronize sewage flow, temperature and demand; average heat does not ensure peak availability.','available heat=m cp DeltaT;m=10;cp=4.18;DeltaT=3','10*4.18*3',125.4,'kW','可提取熱量的顯熱估算~Sensible estimate of extractable heat','疊合24小時熱源和需求曲線。~Overlay24-hour source and demand profiles.','用日均流量選設備可能漏掉夜間低流量。~Sizing from daily mean flow misses low-flow hours.','污水平均溫度足夠就代表全天都有相同熱量。~Adequate mean sewage temperature ensures equal heat all day.'),
 U('二次隔離迴路~Secondary isolation loop','污水與建築迴路以換熱器分隔，降低污染交叉風險但增加溫差與泵功。~An exchanger separates sewage from building loops, reducing cross-contamination pathways while adding approach temperature and pumping.','approach=Tsource-Tsecondary;18-15','18-15',3,'K','端點溫差示例~Illustrative endpoint approach','改變換熱器面積比較接近溫差。~Vary exchanger area and compare approach temperature.','直接把污水當建築循環水會破壞隔離假設。~Directly using sewage as building loop water defeats isolation.','增加隔離換熱器不會改變任何能耗或溫差。~An isolation exchanger changes neither energy use nor temperatures.'),
 U('熱泵能量守恆~Heat-pump energy balance','加熱輸出等於取自熱源的熱加上壓縮機功；不能將COP當熱效率百分比。~Heating output equals source heat plus compressor work; COP is not an efficiency percentage.','Qhot=Qsource+W;120+40','120+40',160,'kW','穩態且其他熱損忽略~Steady state neglecting other heat losses','檢查熱源側、熱端及電表三項是否閉合。~Check closure of source, sink and electricity measurements.','以COP大於1判斷違反守恆是把移熱與發熱混同。~Calling COP above1 a violation confuses heat transfer with heat generation.','熱泵輸出熱量只能小於輸入電功。~Heat-pump heat output must be smaller than electrical input.'),
 U('加熱COP~Heating COP','COP以有用供熱除所需功，邊界須說明包含哪些泵與輔機。~COP divides useful heat by required work; specify included pumps and auxiliaries.','COP=Qhot/W;160/40','160/40',4,'ratio','僅壓縮機功的教學邊界~Teaching boundary including compressor work only','把循環泵納入後重算系統COP。~Include circulation pumps and recalculate system COP.','報壓縮機COP卻聲稱全系統性能會高估效益。~Reporting compressor COP as system performance overstates benefit.','任何設備標示的COP都使用同一能量邊界。~Every stated COP uses the same boundary.'),
 U('溫升與卡諾上限~Temperature lift and Carnot limit','理想上限取決於絕對溫度和溫升；實際壓縮機與換熱不可逆使COP較低。~The ideal bound depends on absolute temperatures and lift; irreversibility lowers actual COP.','COP_Carnot=Th/(Th-Tc);Th=323K;Tc=283K','323/(323-283)',8.075,'ratio','可逆理論上限，非設備預測~Reversible upper bound, not equipment prediction','把熱端升高10K，觀察理想上限變化。~Raise sink temperature10K and observe the ideal bound.','以攝氏計算卡諾COP會失去絕對溫標基礎。~Celsius in Carnot COP loses the absolute-temperature basis.','卡諾COP就是可直接達到的實際設備COP。~Carnot COP is directly achievable equipment COP.'),
 U('污垢熱阻~Fouling resistance','污垢增加熱阻而降低總傳熱係數；壓差與熱阻可能同時變化但不是同一指標。~Fouling adds thermal resistance and lowers U; pressure and thermal resistance may change together but are different measures.','Udirty=1/(1/Uclean+Rf);Uclean=1000;Rf=0.0005','1/(1/1000+0.0005)',666.6666667,'W/m2/K','固定清潔側熱阻~Fixed clean-side resistance','在相同流量比較清洗前後UA及壓差。~Compare UA and pressure before/after cleaning at equal flow.','只依壓差低就判斷傳熱良好可能漏掉薄污膜。~Low pressure loss can miss thermally resistive thin films.','沒有壓差上升就一定沒有傳熱污損。~No pressure rise means no thermal fouling.'),
 U('換熱面積量級~Heat-transfer area estimate','UA與溫差推動決定換熱量；面積估算需保留污垢與流態假設。~UA and temperature difference set heat transfer; retain fouling and flow assumptions in area estimates.','A=Q/(U LMTD);Q=120000W;U=600;LMTD=5K','120000/(600*5)',40,'m2','定U的量級估算~Order-of-magnitude estimate with fixed U','把污垢後U減半，重算面積需求。~Halve fouled U and recalculate required area.','只用清潔U會低估運行後所需面積。~Clean U alone understates operating area needs.','換熱面積與污垢狀態完全無關。~Heat-transfer area is unrelated to fouling.'),
 U('泵功與系統COP~Pumping and system COP','熱源輸送距離和壓降會降低淨效益；小系統的輔機占比可能很高。~Source distance and pressure loss reduce net benefit; auxiliaries can dominate small systems.','COPsystem=Qhot/(Wcomp+Wpumps);160/(40+8)','160/(40+8)',3.333333333,'ratio','同一時段的穩態能量~Steady energy over the same interval','比較遠近熱源的泵電與供熱量。~Compare pumping and heat delivery for near and distant sources.','忽略抽水電力可能把能量搬運成本藏起來。~Ignoring pumping hides the energy cost of transport.','污水熱源免費就代表供熱完全不用電。~A free sewage heat source means heating needs no electricity.'),
 U('季節績效~Seasonal performance','季節績效用累積熱量除累積電量，不能把每小時COP作無權平均。~Seasonal performance divides accumulated heat by electricity, not an unweighted average of hourly COPs.','SPF=(Q1+Q2)/(E1+E2);1000,500,250,200','(1000+500)/(250+200)',3.333333333,'ratio','兩期間示例，含所列輔機~Two-period example including stated auxiliaries','比較直接平均4與2.5和能量加權結果。~Compare the simple average of4 and2.5 with the energy-weighted result.','高COP低負荷時段等權計入會高估全年表現。~Equal weighting of high-COP low-load periods overstates annual performance.','季節COP就是每小時COP的算術平均。~Seasonal COP is the arithmetic mean of hourly COP.'),
 U('熱源影響與異常回退~Source impacts and fault fallback','取熱會降低污水溫度，可能影響下游處理；異常時需回退到已定義的教學安全狀態。~Heat extraction cools sewage and may affect downstream treatment; faults need a defined fallback state in the teaching model.','DeltaT=Qextract/(m cp);Q=100kW;m=10;cp=4.18','100/(10*4.18)',2.392344498,'K','無混合與其他熱源的局部降溫~Local cooling without mixing or other heat sources','模擬污水低流量，檢查取熱後溫度與回退條件。~Simulate low sewage flow and check outlet temperature and fallback conditions.','以固定取熱功率運行於低流量會過度降溫。~Fixed extraction at low flow can cause excessive cooling.','取出的熱量不會改變污水下游溫度。~Extracted heat does not change downstream wastewater temperature.')])

C(465,'可追溯時序、基準模型與不確定負載~Traceable time series, baselines and uncertain demand','environment-urban',
 ['電表與氣象~Meters and weather','時間對齊~Time alignment','特徵~Features','預測模型~Forecast model','時間外驗證~Temporal validation','調度~Dispatch'],['load','loadbench'],[
 U('功率與能量區別~Distinguish power and energy','電表區間能量需除時間才能形成平均功率；不同採樣頻率需統一。~Divide interval energy by duration to get mean power and harmonize sampling intervals.','P=E/dt;E=25kWh;dt=0.25h','25/0.25',100,'kW','區間平均，不是瞬時峰值~Interval mean, not instantaneous peak','把15分鐘資料聚合到小時並檢查能量守恆。~Aggregate15-minute data hourly and verify energy conservation.','直接相加功率卻不乘時間會弄錯日能耗。~Summing powers without time miscalculates daily energy.','kW和kWh是同一物理量。~kW and kWh are the same quantity.'),
 U('時區與缺測~Time zones and missing intervals','時區、日光節約與遺漏區間會造成重複或空洞；須保存原始時間戳。~Time zones, daylight saving and missing intervals cause duplicates or gaps; retain original timestamps.','coverage=observed intervals/expected;92/96','92/96',0.958333333,'fraction','示例24小時的15分鐘資料~Illustrative24-hour day of15-minute data','造一個缺測區間，標記而不把它當零負載。~Create a missing interval and flag it rather than treating it as zero.','補零會讓模型學到不存在的停機。~Zero-filling teaches a shutdown that never occurred.','缺測電表值就等於用電為零。~A missing meter value means zero consumption.'),
 U('季節性樸素基準~Seasonal naive baseline','先以同星期同時段或前一日建立可解釋基準，再判斷複雜模型是否改善。~Establish an interpretable same-weekday/time or previous-day baseline before judging complex models.','absolute error=abs(actual-baseline);abs(110-100)','abs(110-100)',10,'kW','單一時點誤差~Single-point error','比較昨日同時與上週同時兩個基準。~Compare previous-day and previous-week baselines.','沒有基準就宣稱AI較好缺乏比較依據。~Claiming superior AI without a baseline lacks comparison.','模型越複雜就必定勝過樸素基準。~A more complex model always beats a naive baseline.'),
 U('氣象與度時~Weather and degree-hours','冷暖需求可用基準溫度以上或以下的度時描述，但轉折和用途需要資料校正。~Degree-hours above or below a base describe demand, but breakpoints and use require calibration.','cooling degree-hours=max(T-Tbase,0)*dt;T=30;Tbase=24;dt=1h','max(30-24,0)*1',6,'K h','單時段線性特徵，不是完整建築模型~One-interval linear feature, not a full building model','改變基準溫度，檢查不同季節殘差。~Change base temperature and inspect seasonal residuals.','使用預測時尚未知的實測未來天氣會造成資料洩漏。~Using unavailable future observed weather causes leakage.','模型訓練可任意使用未來實測資料作即時特徵。~Training may freely use future measurements as real-time features.'),
 U('線性可解釋模型~Interpretable linear model','基載、天氣和占用項提供可檢查的貢獻，係數須由訓練集估計。~Baseload, weather and occupancy give inspectable contributions; estimate coefficients from training data.','P=b0+bT*CDH+bOcc*Occ;b0=40;bT=5;CDH=6;bOcc=20;Occ=1','40+5*6+20*1',90,'kW','假想係數，未經真實場址校正~Hypothetical coefficients without real-site calibration','停用占用項並比較工作日與假日偏差。~Remove occupancy and compare weekday/weekend bias.','把係數因果化可能忽略天氣和占用的相關性。~Interpreting coefficients causally can miss correlated inputs.','回歸係數永遠能直接解釋物理因果。~A regression coefficient always proves physical causation.'),
 U('時間外驗證~Out-of-time validation','依時間先後切分，避免相鄰時間或未來資料洩漏到訓練；超參數需在驗證集選。~Split chronologically to avoid future and adjacent-window leakage; select hyperparameters on validation data.','test fraction=test days/total days;30/180','30/180',0.166666667,'fraction','示意切分比例，不是通用最佳比例~Illustrative split, not a universal optimum','用滾動起點依序預測下一週。~Use rolling origins to predict each next week.','隨機打散強季節資料可能高估未來預測能力。~Random shuffling of seasonal data can overstate future performance.','所有時間序列都應隨機打散後測試。~Every time series should be tested after random shuffling.'),
 U('MAE與尖峰誤差~MAE and peak errors','平均絕對誤差描述典型偏差，但調度還需關心尖峰低估與時刻錯位。~MAE describes typical error, while dispatch also needs peak underprediction and timing error.','MAE=(10+5+15)/3','(10+5+15)/3',10,'kW','三個假想誤差樣本~Three hypothetical error samples','分別報尖峰時段和非尖峰時段MAE。~Report MAE separately for peak and off-peak periods.','平均誤差小仍可能在最重要尖峰嚴重低估。~Small average error can coexist with severe peak underprediction.','MAE小即可保證每一個尖峰都預測準確。~Small MAE guarantees every peak is accurate.'),
 U('預測區間與涵蓋率~Prediction intervals and coverage','區間寬度與涵蓋率需一起報告；只報點預測無法表達調度風險。~Report width with coverage; a point forecast alone cannot express dispatch uncertainty.','coverage=inside intervals/total;18/20','18/20',0.9,'fraction','有限樣本的經驗涵蓋率~Empirical coverage from a finite sample','比較窄區間與寬區間的漏包情況。~Compare missed observations under narrow and wide intervals.','不斷加寬區間可提高涵蓋卻降低操作價值。~Widening intervals raises coverage while reducing usefulness.','涵蓋率高就代表區間一定精準而且實用。~High coverage automatically means precise useful intervals.'),
 U('概念漂移與重新校正~Concept drift and recalibration','設備更新、作息與氣候改變會讓歷史關係失效；需監測殘差而非自動永久相信模型。~Equipment, schedules and climate change historical relationships; monitor residuals rather than trust the model indefinitely.','bias=mean residual;(8+10+12)/3','(8+10+12)/3',10,'kW','三時點平均偏差~Mean bias over three points','模擬新增一台設備，檢查殘差是否持續偏正。~Simulate an added load and check sustained positive residuals.','只用全歷史平均誤差可能稀釋近期漂移。~An all-history mean can dilute recent drift.','模型訓練一次就能永久適用所有設備狀況。~A model trained once works forever for all equipment states.'),
 U('預測轉為儲能調度~Translate forecasts into storage dispatch','預測需受功率、能量、效率和服務條件約束；不確定度應保留到決策。~Forecasts must respect power, energy, efficiency and service constraints; carry uncertainty into decisions.','required delivered energy=(Ppeak-Plimit)*duration;(150-120)*2','(150-120)*2',60,'kWh','理想負載削峰，不含充放損失~Ideal delivered peak shaving before charging/discharging losses','加入效率與容量限制，檢查是否仍可削峰。~Add efficiency and capacity limits and check feasibility.','把預測峰值直接當充放電命令會忽略儲能狀態。~Using forecast peaks directly as dispatch ignores storage state.','只要能預測尖峰，就一定有足夠設備消除尖峰。~Predicting a peak guarantees enough equipment to eliminate it.')])

C(466,'進料排程、氣固輸送與封閉收集~Inlet scheduling, gas-solid transport and enclosed collection','environment-recycling',
 ['投入口~Waste inlet','暫存閥~Storage valve','地下管網~Pipe network','分離器~Separator','風機~Fan','壓實容器~Compaction container'],['envac','ita'],[
 U('住戶投料與尖峰~Household input and peaks','垃圾產生量與投入口事件須分開；一天總量不能直接決定單次管路輸送需求。~Separate generated mass from inlet events; daily totals do not determine a single transport batch.','daily mass=N m;N=200 households;m=2 kg/day','200*2',400,'kg/day','假想住戶負荷~Hypothetical household load','比較分散投料與晚間集中投料。~Compare distributed and evening-clustered disposal.','以平均值排程可能在投料尖峰滿槽。~Average-based schedules can overflow storage at peaks.','日平均負荷足夠就代表任何尖峰都能處理。~Adequate daily average capacity handles every peak.'),
 U('入口暫存容積~Inlet storage volume','暫存把不連續投料與分批輸送解耦；容積取決於堆積密度和容許填充。~Storage decouples intermittent disposal from batch transport; volume depends on bulk density and usable fill.','V=M/rho;M=80kg;rho=100kg/m3','80/100',0.8,'m3','未壓實垃圾的假想密度~Hypothetical uncompacted bulk density','加入蓬鬆紙箱情境，保持質量但降低密度。~Add bulky-cardboard conditions at equal mass and lower density.','只用重量監測可能漏掉低密度垃圾塞滿入口。~Mass-only monitoring can miss volume blockage by light waste.','同樣重量垃圾一定占相同容積。~Equal waste mass always occupies equal volume.'),
 U('管內氣流速度~Air speed in the pipe','輸送以空氣拖曳和壓差移動物料；速度需與管徑、物料形狀和載荷共同考慮。~Air drag and pressure move waste; assess speed with diameter, shape and loading.','v=Q/A;Q=2m3/s;D=0.4m;A=pi D^2/4','2/(pi*0.4**2/4)',15.91549431,'m/s','單點實際體積流率，未做全程可壓縮解~Actual local flow rate, not a full compressible solution','改變管徑並觀察速度與可輸送物尺寸限制。~Vary diameter and inspect speed and item-size constraints.','把風機標況流量直接當每處實際流量會偏估速度。~Using standardized fan flow as local actual flow misestimates speed.','管路各處的標準體積流量與實際體積流量完全相同。~Standardized and actual volume flow are identical everywhere.'),
 U('支路壓降與彎管~Branch losses and bends','彎管、閥與固體加速增加壓損；清氣管路式只能提供部分基準。~Bends, valves and solid acceleration add losses; clean-air equations provide only a partial baseline.','minor loss=K rho v^2/2;K=2;rho=1.2;v=15','2*1.2*15**2/2',270,'Pa','清氣局部損失示例，不含氣固兩相效應~Clean-air local-loss example excluding two-phase effects','比較有無彎管的教學壓差並標出模型缺項。~Compare teaching pressure drops with/without a bend and list missing physics.','以清氣壓降當載料總壓降會低估風機需求。~Clean-air pressure loss understates loaded transport demand.','垃圾加入氣流後完全不影響壓降。~Adding waste to airflow does not affect pressure loss.'),
 U('批次調度與互斥~Batch scheduling and mutual exclusion','同一管段的多入口需要排程，避免同時放料超過可輸送負荷。~Schedule inlets sharing a pipe to prevent simultaneous release beyond transport capacity.','utilization=active time/window;8*45/600','8*45/600',0.6,'fraction','八批各45秒的假想排程~Hypothetical eight batches of45 seconds','加上一批延遲，檢查衝突與剩餘裕度。~Add one delayed batch and check conflicts and margin.','只依入口各自需求啟動可能造成共享管段過載。~Independent inlet triggers can overload shared pipe segments.','每個入口都能同時全開而互不影響。~Every inlet can fully open simultaneously without interaction.'),
 U('漏氣與風量損失~Leaks and lost air capacity','漏氣占用風機流量，降低有效輸送；以隔離支路比較壓力可定位。~Leaks consume fan capacity and reduce useful transport; isolate branches and compare pressure.','useful air=Qfan-Qleak;2.0-0.3','2.0-0.3',1.7,'m3/s','同一測點狀態的體積收支~Volume balance at the same thermodynamic state','逐段隔離教學閥門並記錄壓力恢復。~Isolate simulated valves sequentially and record pressure recovery.','漏氣可能讓風機耗電正常卻輸送失敗。~Leaks can cause failed transport despite apparently normal fan power.','風機有轉就代表管網一定沒有漏氣。~A running fan proves the network is airtight.'),
 U('分離器與排氣~Separator and exhaust','固氣分離保護風機與排氣品質；分離器壓差、集料重量和濾材狀態需聯合判讀。~Separation protects the fan and exhaust quality; interpret pressure, collected mass and filter condition together.','capture=collected/inlet solids;98/100','98/100',0.98,'fraction','總固體捕集示例，未代表細粉性能~Total-solids capture example, not fine-particle performance','將粗垃圾和粉塵分開做質量收支。~Balance coarse waste and fine dust separately.','高總捕集率可能掩蓋細粉穿透。~High bulk capture can hide fine-particle penetration.','捕住大件垃圾就代表排氣沒有細粉。~Capturing large waste proves dust-free exhaust.'),
 U('風機電耗邊界~Fan electricity boundary','壓差乘氣量是小壓差近似的流體功；壓縮效應與效率需在詳算納入。~Pressure difference times flow approximates fluid power at small pressure ratios; detailed work includes compression and efficiency.','P=DeltaP Q/eta;DeltaP=10000Pa;Q=2;eta=0.65','10000*2/0.65/1000',30.76923077,'kW','小壓比量級估算，非風機選型~Low-pressure-ratio estimate, not fan selection','保持質量輸送任務比較兩種批次長度的電量。~Compare electricity for two batch durations at equal transported mass.','只看額定功率而忽略運轉時數會誤判能耗。~Rated power without operating hours misjudges energy.','風機功率較小就必定有較低每噸電耗。~A lower-power fan always has lower energy per tonne.'),
 U('堵塞診斷與隔離~Blockage diagnosis and isolation','壓力突變、輸送時間和到站重量可區分缺料、漏氣和堵塞；操作僅在隔離教學模型進行。~Pressure changes, travel time and arrival mass distinguish empty feed, leaks and blockages; act only in the isolated teaching model.','unarrived mass=sent-arrived;50-42','50-42',8,'kg','忽略秤重誤差的診斷線索~Diagnostic clue neglecting weighing error','加入一個假想堵塞，觀察壓差和質量差是否同時變化。~Inject a simulated blockage and compare pressure and mass residuals.','未確認隔離就增加輸送次數可能加劇堵塞。~Repeated transport without diagnosis can worsen a blockage.','任何輸送異常都應直接加大風機速度。~Every transport fault should be solved by higher fan speed.'),
 U('物流終端與效益比較~Terminal logistics and comparison','真空收集把部分路面物流移到終端，仍需容器搬運、電力與維護；邊界需一致。~Pneumatic collection shifts some surface logistics to a terminal but still needs container handling, power and maintenance; compare equal boundaries.','specific energy=E/mass;120kWh/4tonne','120/4',30,'kWh/tonne','假想運行資料，非任何廠商性能保證~Hypothetical operation, not a vendor guarantee','納入終端車輛與風機後比較相同收集量。~Include terminal vehicles and fans for equal collected mass.','只比較路邊車次會漏掉地下系統耗能。~Roadside truck counts alone omit underground-system energy.','沒有路邊垃圾車就代表收集系統零能耗。~No curbside truck means zero collection energy.')])

C(467,'光譜辨識、噴嘴時序與回收品質~Spectral recognition, ejector timing and recovery quality','environment-recycling',
 ['均勻送料~Uniform feed','照明~Illumination','光譜與影像~Spectra and images','分類器~Classifier','氣動噴嘴~Air ejector','產品抽驗~Product sampling'],['tomra','nir'],[
 U('物料組成與目標~Feed composition and target','先定義欲回收物與污染物，純度和回收率才有明確分母。~Define target and contaminant classes before calculating purity and recovery.','target mass=feed*target fraction;1000*0.3','1000*0.3',300,'kg/h','單一目標聚合物的假想進料~Hypothetical feed for one target polymer','把進料中PET比例改變，觀察分母。~Vary feed PET fraction and track denominators.','以總進料作回收率分母會混同產率。~Using total feed as recovery denominator confuses yield.','產品質量除總進料就是目標物回收率。~Product mass divided by total feed is target recovery.'),
 U('單層送料與遮蔽~Monolayer feeding and occlusion','相互覆蓋讓下層物料無法被辨識，均勻送料常比單純提高模型複雜度更重要。~Overlapping items hide lower layers; uniform feeding can matter more than classifier complexity.','visible fraction=uncovered/total;850/1000','850/1000',0.85,'fraction','可視物件數示例~Illustrative visible object count','固定相機設定，改變送料厚度比較漏檢。~Keep camera settings and vary bed depth to compare misses.','雙層物料可能讓光譜代表上件而噴嘴吹走下件。~Two layers can make spectra identify the upper object while the jet moves another.','演算法可從完全不透明覆蓋下直接看見所有物料。~An algorithm directly sees everything beneath opaque cover.'),
 U('光譜訊噪比~Spectral signal-to-noise ratio','材質辨識依光譜特徵與噪音差異，髒污、濕度和表面顏色會改變訊號。~Material recognition depends on spectral features relative to noise; dirt, moisture and colour alter signals.','SNR=signal/noise;signal=120;noise=6','120/6',20,'ratio','線性振幅比，非分貝~Linear amplitude ratio, not decibels','量測乾淨和髒污樣本的光譜差異。~Compare spectra of clean and dirty samples.','以訓練時乾燥樣本套用潮濕進料會產生域偏移。~A dry training set can fail on wet feed through domain shift.','同種塑膠在任何污損狀態都有完全相同光譜。~One plastic has identical spectra under every contamination state.'),
 U('像素與物件尺寸~Pixels and object size','空間解析度需能分辨最小欲分選物；相機視野加寬會增加每像素尺寸。~Resolve the minimum target size; widening the field increases millimetres per pixel.','pixel size=FOV/pixels;1000mm/1000','1000/1000',1,'mm/pixel','正投影中心近似~Central orthographic approximation','把視野加倍但像素數不變，檢查小物件。~Double field of view at fixed pixels and inspect small objects.','只報相機總像素不提供視野會無法判斷分辨力。~Pixel count without field of view does not establish resolution.','像素數相同的相機在任何視野都有相同物體解析度。~Equal pixel counts give equal object resolution at any field of view.'),
 U('分類精確率~Classification precision','精確率衡量被選中者有多少是真目標；需與召回率分開。~Precision measures how many selected items are true targets and differs from recall.','precision=TP/(TP+FP);TP=90;FP=10','90/(90+10)',0.9,'fraction','物件數基準，非質量純度~Object-count basis, not mass purity','加入大質量誤判物，比較計數精確率與質量純度。~Add a heavy false positive and compare count precision with mass purity.','少量重污染物可能嚴重降低質量純度。~A few heavy contaminants can strongly reduce mass purity.','物件數精確率必定等於產品質量純度。~Count precision always equals product mass purity.'),
 U('召回率與漏失~Recall and missed recovery','召回率以真目標總數為分母；提高閾值常增加純度卻減少回收。~Recall uses all actual targets as denominator; a stricter threshold often increases purity while reducing recovery.','recall=TP/(TP+FN);TP=90;FN=30','90/(90+30)',0.75,'fraction','相同測試批次~Same test batch','繪出三個分類閾值的精確率與召回率。~Plot precision and recall for three thresholds.','只報純度可能掩蓋大量目標流入殘渣。~Purity alone can hide target loss to residue.','純度提高就代表回收率一定提高。~Higher purity necessarily means higher recovery.'),
 U('輸送帶與噴嘴延遲~Belt travel and ejector delay','辨識位置到噴嘴的輸送時間為距離除帶速；發送命令的等待時間須扣除通訊及閥門響應，確保氣流與物件同時到位。~Transport time is sensing-to-nozzle distance divided by belt speed; subtract communication and valve response from command waiting time so jet and object arrive together.','command wait=L/v-tcommunication-tvalve;L=1.2m;v=3m/s;delays=0.02s,0.03s','1.2/3-0.02-0.03',0.35,'s','物件不滑動且延遲已校正；等待時間不得為負~No object slip and calibrated delays; command wait cannot be negative','帶速增加10%，同步調整觸發時間。~Increase belt speed ten percent and update trigger timing.','固定延遲遇到變速會噴錯位置。~Fixed delay during speed changes ejects the wrong position.','輸送帶變速不需更新噴嘴時序。~Belt speed changes require no ejector timing update.'),
 U('噴嘴解析與氣耗~Jet resolution and air use','噴嘴間距與脈寬決定選擇範圍，也會帶走鄰近物；氣耗需按觸發次數估計。~Nozzle spacing and pulse width set the affected region and may entrain neighbors; estimate air by trigger count.','air volume=flow*pulse*events;0.002m3/s*0.03s*1000','0.002*0.03*1000',0.06,'m3','同一壓力狀態的假想體積~Hypothetical volume at one pressure state','比較單噴嘴與相鄰噴嘴同觸發的夾帶。~Compare entrainment from one versus adjacent jets.','脈寬過長會提高誤帶和壓縮空氣需求。~An overly long pulse increases entrainment and air demand.','噴嘴脈寬越長就一定分得越精準。~Longer ejector pulses always improve precision.'),
 U('質量收支與抽樣~Mass balance and sampling','產品、殘渣與設備滯留需閉合；抽樣要覆蓋整段生產變動。~Close product, residue and holdup mass; sample production variability.','closure=(product+residue)/feed;(320+670)/1000','(320+670)/1000',0.99,'fraction','缺口包含滯留與量測誤差~Gap includes holdup and measurement error','在不同時段抽樣，不只抓最乾淨一把產品。~Sample multiple times rather than the cleanest handful.','不具代表性樣品會高估全批純度。~Unrepresentative samples overstate batch purity.','一把乾淨產品足以證明整天產品品質。~One clean handful proves all-day quality.'),
 U('模型漂移與人工複核~Model drift and human review','包材、顏料和光源老化會改變分類分布；需保留標註、版本與盲測。~Packaging, pigments and lamp aging shift classification; retain labels, versions and blind tests.','error-rate increase=0.08-0.03','0.08-0.03',0.05,'fraction points','絕對錯誤率差~Absolute error-rate difference','用新包材建立保留測試集並比較版本。~Create a held-out new-packaging set and compare versions.','用同批訓練樣本報性能會高估泛化。~Reporting training-set performance overstates generalization.','AI分選器訓練後永遠不需重新驗證。~An AI sorter never needs revalidation after training.')])

C(468,'導電感應、粒子軌跡與非鐵回收~Induction, particle trajectories and non-ferrous recovery','environment-recycling',
 ['篩分~Screening','除鐵~Ferrous removal','均勻送料~Uniform feeding','磁轉子~Magnetic rotor','分料板~Splitter','產品檢查~Product checks'],['steinert','meri'],[
 U('非鐵目標與前處理~Non-ferrous targets and pretreatment','渦電流分選依導電性產生作用，並不等於傳統鐵磁吸附；先排除鐵件和尺寸極端物。~Eddy-current action depends on conductivity, unlike ferromagnetic attraction; remove ferrous and extreme-size items first.','target mass=feed*nonferrous fraction;500*0.12','500*0.12',60,'kg/h','假想非鐵質量比例~Hypothetical non-ferrous fraction','把鐵、鋁和塑膠分別標示輸送路徑。~Trace steel, aluminium and plastic paths separately.','鐵件進入高速轉子區可能影響設備與分選。~Ferrous pieces entering the rotor zone can disrupt sorting and equipment.','渦電流分選就是用磁鐵吸住所有金屬。~Eddy-current sorting simply magnetically attracts every metal.'),
 U('變動磁場與感應~Changing field and induction','粒子經歷的磁通變化誘發電流，再與磁場作用改變軌跡；靜止均勻磁場不是同一機制。~Changing magnetic flux induces currents that interact with the field and alter trajectories; a static uniform field differs.','emf magnitude=N DeltaPhi/DeltaT;N=1;DeltaPhi=0.002Wb;dt=0.01s','1*0.002/0.01',0.2,'V','簡化單迴路感應示例，非粒子完整模型~Simple loop example, not a full particle model','比較磁通變化時間加倍後的感應量級。~Double flux-change time and compare induced voltage.','只看磁場強度而忽略變化率會漏掉感應來源。~Field strength alone misses the role of flux-change rate.','完全不變的磁通仍會持續誘發同樣電動勢。~Unchanging flux continuously induces the same emf.'),
 U('導電率與形狀~Conductivity and shape','回路電阻受導電率、尺寸與形狀影響；相同金屬質量不代表相同電磁力。~Loop resistance depends on conductivity, size and shape; equal metal mass does not imply equal force.','R=rho L/A;rho=2.8e-8ohm m;L=0.1m;A=1e-6m2','2.8e-8*0.1/1e-6',0.0028,'ohm','示意鋁導體迴路，不含高頻集膚~Illustrative aluminium loop without skin effects','比較薄片與團塊的等效迴路。~Compare equivalent loops for flakes and compact pieces.','用金屬名稱單獨預測拋射距離會忽略形狀。~Metal name alone misses shape effects on throw.','同一材質所有形狀都會飛到同一位置。~Every shape of one material lands at the same point.'),
 U('粒徑分級~Particle-size classification','尺寸窄化可減少不同動力學混在同一分料設定；細粒需不同解析能力。~Narrow size classes reduce mixed dynamics under one splitter setting; fines need different resolution.','size ratio=dmax/dmin;40mm/10mm','40/10',4,'ratio','粒級跨度指標~Particle-size-span indicator','將寬粒級分成兩段再比較回收純度。~Split a broad size class and compare recovery purity.','一個分料板位置可能同時漏小粒又夾帶大粒。~One splitter position can miss fines while entraining coarse items.','全部粒徑混在一起一定比篩分後好分。~All sizes mixed are always easier to separate.'),
 U('輸送速度與自然落點~Belt speed and gravity trajectory','先以無電磁作用的拋體落點作基準，再觀察非鐵偏移；空阻和碰撞另列。~Establish a gravity-only baseline before electromagnetic deflection; treat drag and collisions separately.','t=sqrt(2h/g);h=0.5m;g=9.81','sqrt(2*0.5/9.81)',0.319275428,'s','水平離帶、無空阻~Horizontal release without air drag','量測塑膠基準落點再加入鋁片。~Measure a plastic baseline landing point before adding aluminium.','沒有自然軌跡基準會把帶速差當電磁差。~Without a baseline belt-speed effects look electromagnetic.','所有落點差異都只由電磁作用造成。~Every landing-point difference is electromagnetic.'),
 U('分料板位置~Splitter location','分料板在純度與回收率間取捨，需看兩群落點分布的重疊。~The splitter trades purity against recovery according to overlapping landing distributions.','gravity range=v t;v=2m/s;t=0.319275428s','2*0.319275428',0.638550856,'m','同前一單元的理想基準~Same ideal baseline as the preceding unit','逐步移動分料板並記錄兩個產品流質量。~Move the splitter incrementally and weigh both outputs.','只看非鐵回收增加可能漏掉非金屬夾帶。~Higher non-ferrous recovery can hide nonmetal entrainment.','分料板向外移就能同時無限提高純度與回收。~Moving the splitter outward raises purity and recovery without limit.'),
 U('單層料與碰撞~Monolayer feeding and collisions','粒子互撞與重疊可遮蔽電磁作用；送料均勻度決定可重複性。~Collisions and overlap obscure electromagnetic effects; uniform feeding governs repeatability.','bed loading=mass flow/(belt width*speed);2kg/s/(1m*2m/s)','2/(1*2)',1,'kg/m2','平均面載量，未提供粒子厚度~Mean areal loading without particle-thickness estimate','固定轉子條件，減少送料量比較落點分布。~Keep rotor conditions and reduce feed to compare landing distributions.','過量送料可能讓鋁片被其他物拖住。~Overfeeding can trap aluminium beneath other material.','送料越厚就一定有越高單機回收率。~A thicker bed always raises recovery.'),
 U('純度與回收率雙指標~Purity and recovery together','產品非鐵比例與進料非鐵回收比例有不同分母，應同時報告。~Product non-ferrous fraction and recovered feed-target fraction have different denominators; report both.','recovery=target recovered/target feed;54/60','54/60',0.9,'fraction','質量基準~Mass basis','若產品總量60kg/h，另算純度並與回收率比較。~For60kg/h total product also calculate purity and compare recovery.','高產品量可能主要是夾帶而非回收更多金屬。~High product output may be entrainment rather than metal recovery.','產品流量增加就證明分選效率提高。~More product flow proves better separation.'),
 U('磨耗與間隙漂移~Wear and gap drift','皮帶厚度、轉子位置與表面磨耗會改變粒子距磁場的距離；維護需有基準。~Belt thickness, rotor position and wear change particle-field distance; maintenance needs reference measurements.','relative gap change=(8-6)/6','(8-6)/6',0.333333333,'fraction','幾何變化，不推定力的同比關係~Geometric change without proportional-force assumption','用固定標準樣件比較維護前後落點。~Compare standard-particle landing before/after maintenance.','只依轉速正常判定整機正常可能漏掉間隙變化。~Normal rotor speed can conceal a changed gap.','轉速不變就代表所有電磁分選條件都不變。~Unchanged rotor speed means all separation conditions are unchanged.'),
 U('能耗與殘渣價值~Energy and residual value','比較同進料組成下每噸電耗和殘渣金屬損失，避免只追求最高轉速。~Compare energy per tonne and metal loss under equal feed composition rather than maximum speed alone.','specific electricity=power/throughput;15kW/2tonne/h','15/2',7.5,'kWh/tonne','假想完整單機電表~Hypothetical whole-machine meter','比較兩種轉速的電耗、純度與回收率。~Compare energy, purity and recovery at two speeds.','提高轉速若回收改善小，可能降低整體資源效益。~Higher speed with little recovery gain can worsen resource performance.','轉速越高永遠越節能。~Higher rotor speed is always more energy efficient.')])

C(469,'玻璃色系、陶瓷污染與品質收支~Glass colours, ceramic contamination and quality balances','environment-recycling',
 ['破袋與篩分~Opening and screening','金屬移除~Metal removal','顏色影像~Colour imaging','異物辨識~Contaminant identification','噴選~Ejection','玻璃產品~Cullet product'],['recycle','nir'],[
 U('玻璃來源與規格~Glass sources and specifications','容器玻璃、耐熱玻璃與陶瓷成分不同；先分用途與材料來源才能設定產品品質。~Container glass, heat-resistant glass and ceramics differ in composition; define source and use before product quality.','target cullet=feed*fraction;1000*0.85','1000*0.85',850,'kg/h','假想容器玻璃比例~Hypothetical container-glass fraction','將耐熱玻璃與陶瓷獨立標籤。~Label heat-resistant glass and ceramics separately.','把透明物都當同類玻璃會引入不相容材料。~Treating every transparent item as the same glass admits incompatible material.','所有透明碎片都可視為同一種容器玻璃。~All transparent fragments are the same container glass.'),
 U('顏色照明與白平衡~Colour illumination and white balance','顏色判斷依光源光譜、曝光和背景，需用標準色樣維持一致。~Colour classification depends on illumination spectrum, exposure and background; use reference samples for consistency.','normalized channel=G/(R+G+B);R=20,G=60,B=20','60/(20+60+20)',0.6,'fraction','簡化色特徵，不是完整分類器~Simplified colour feature, not a complete classifier','降低光源強度並檢查歸一化及噪音。~Reduce illumination and check normalization and noise.','光源老化可能讓相同玻璃跨越色類閾值。~Lamp aging can move the same glass across colour thresholds.','相機RGB值與照明條件完全無關。~Camera RGB values are independent of lighting.'),
 U('透射與不透明異物~Transmission and opaque contaminants','透射與反射資訊互補；單靠顏色可能把同色陶瓷誤認成玻璃。~Transmission and reflection complement each other; colour alone can confuse same-colour ceramics with glass.','transmission=I/I0;30/100','30/100',0.3,'fraction','固定厚度與波段~Fixed thickness and wavelength band','比較同色玻璃與陶瓷的透射訊號。~Compare transmission of same-colour glass and ceramics.','碎片厚度差異也會影響透射，不能全解讀成材質差。~Thickness also affects transmission and is not purely a material signal.','同顏色就必定是同種材質。~Equal colour guarantees equal material.'),
 U('粒徑與細粉~Size and fines','細粉使影像辨識和氣動分選更困難，篩分可建立適當處理路徑。~Fines challenge imaging and pneumatic sorting; screening assigns suitable processing paths.','fines fraction=mass fines/feed;80/1000','80/1000',0.08,'fraction','質量基準~Mass basis','比較篩分前後相機可辨識物件比例。~Compare recognizable objects before and after screening.','細粉堆積在鏡頭或燈具會增加誤判。~Fines on optics increase classification errors.','碎得越細就一定越容易做顏色辨識。~Finer crushing always makes colour recognition easier.'),
 U('鐵與非鐵前段移除~Upstream ferrous and non-ferrous removal','磁選和渦電流針對不同金屬，應在玻璃色選前減少混入與設備磨耗。~Magnets and eddy-current systems address different metals and reduce contamination and wear before colour sorting.','metal residual=Min(1-eta);10*(1-0.95)','10*(1-0.95)',0.5,'kg/h','單一假想金屬去除步驟~One hypothetical metal-removal stage','分別秤重鐵與非鐵產品，核對殘餘。~Weigh ferrous and non-ferrous products separately.','只設磁選會留下非鐵金屬。~Magnetic sorting alone leaves non-ferrous metals.','磁鐵可以同樣吸走鐵、鋁與銅。~A magnet removes iron, aluminium and copper equally.'),
 U('噴選時序~Ejection timing','碎玻璃在皮帶上可能滑動或旋轉，速度追蹤要和噴嘴觸發聯繫。~Cullet can slip or rotate; link velocity tracking to ejector triggers.','delay=L/v;0.8/2','0.8/2',0.4,'s','無滑動基準~No-slip baseline','在模型加入速度偏差，量出噴選落點誤差。~Add speed error in the model and measure ejection-position error.','只依皮帶速度而忽略碎片滑動會偏移觸發。~Belt speed alone misses fragment slip.','所有碎片速度都永遠等於皮帶速度。~Every fragment always moves at belt speed.'),
 U('微量陶瓷污染~Trace ceramic contamination','少量不熔雜質可能影響下游熔製品質，需用足夠代表性的樣本估微量比例。~Small refractory contaminants can affect downstream melting; estimate trace fractions with representative samples.','contamination ppm=mass impurity/mass product*1e6;0.02/1000*1e6','0.02/1000*1e6',20,'ppm by mass','僅示例濃度，非任何玻璃廠允收值~Example concentration, not a plant acceptance limit','增加樣本量並記錄稀有陶瓷片的檢出。~Increase sample mass and record rare ceramic detections.','小樣本未見異物不能證明全批零污染。~No contaminant in a small sample does not prove a clean batch.','抽一小杯未見陶瓷即可證明整批零陶瓷。~A clean small cup proves zero ceramics in the whole batch.'),
 U('顏色純度與收率~Colour purity and yield','色別產品應同時報純度與質量收率，過嚴剔除可能浪費合格玻璃。~Report colour purity and mass yield together; overly strict rejection can waste suitable glass.','purity=correct-colour mass/product mass;570/600','570/600',0.95,'fraction','單一色系產品~Single-colour product','比較兩個顏色閾值下的純度—收率曲線。~Compare purity-yield curves for two colour thresholds.','只追求純度會讓大量同色玻璃進殘渣。~Purity-only optimization can lose much suitable glass.','剔除越多就一定是較好的回收策略。~Rejecting more material always improves recycling.'),
 U('清洗水與標籤~Wash water and labels','附著有機物和標籤會遮蔽光學訊號；清洗改善辨識但產生污水與能耗。~Labels and organics obscure optical signals; washing helps recognition but uses water and energy and creates wastewater.','freshwater=circulation*(1-recycle fraction);5*(1-0.8)','5*(1-0.8)',1,'m3/h','未含蒸發和帶出補水~Excludes evaporation and carryout makeup','把循環水濁度升高，觀察清洗與成像品質。~Increase recycle-water turbidity and inspect cleaning and imaging.','循環率高但污物累積會讓產品再污染。~High recycle with contaminant buildup can re-soil product.','清洗水循環率越高永遠越乾淨。~Higher wash-water recycling always produces cleaner water.'),
 U('批次追溯與熔製回饋~Batch traceability and melting feedback','產品批次需連結來源、色選參數、抽樣與下游回饋，才能定位異物來源。~Link batches to sources, sorting settings, samples and downstream feedback to locate contamination.','traceable fraction=identified batches/total;47/50','47/50',0.94,'fraction','追溯完整度，非產品品質率~Traceability completeness, not product quality','模擬一個異常批次反查送料與分類版本。~Trace one abnormal batch back to feed and classifier version.','把多來源任意混料會使原因難以回溯。~Unrecorded source mixing obscures root causes.','產品外觀相同就不需保留來源批次。~Identical appearance removes the need for source batches.')])

C(470,'纖維解離、油墨浮選與水循環~Fiber liberation, ink flotation and water circulation','environment-recycling',
 ['廢紙分級~Paper grading','碎漿~Pulping','篩選除渣~Screening and cleaning','浮選~Flotation','洗滌濃縮~Washing and thickening','白水循環~Process-water loop'],['flotation','dip'],[
 U('進料乾纖維基準~Dry-fiber feed basis','含水廢紙質量需換成乾固體基準，否則不同批次收率不可比。~Convert wet recovered-paper mass to dry solids for comparable yields.','dry mass=wet mass*(1-moisture);1000*(1-0.1)','1000*(1-0.1)',900,'kg','濕基含水率~Wet-basis moisture','比較含水10%與20%的同重進料。~Compare equal wet feed at10% and20% moisture.','以濕重計產率會把水分當纖維。~Wet-mass yield counts water as fiber.','回收紙重量越大就一定含有越多乾纖維。~Heavier recovered paper always contains more dry fiber.'),
 U('碎漿濃度~Pulping consistency','碎漿濃度是乾固體占漿液質量，影響混合、能耗與纖維解離。~Consistency is dry solids over slurry mass and affects mixing, energy and fiber liberation.','consistency=Mdry/Mslurry;900/15000','900/15000',0.06,'fraction','質量分率，不是體積分率~Mass fraction, not volume fraction','保持乾纖維量，增加水量比較濃度。~Keep dry fiber fixed and add water to compare consistency.','將百分濃度直接代入分率公式會差100倍。~Using percent as fraction introduces a hundredfold error.','6%濃度在計算中應填6而非0.06。~6% consistency should be entered as6 rather than0.06.'),
 U('解離能量與纖維保護~Liberation energy and fiber protection','機械能促進紙張解離，但過度作用會增加纖維損傷與細料。~Mechanical energy liberates paper but excessive action increases fiber damage and fines.','specific energy=E/Mdry;90kWh/0.9tonne','90/0.9',100,'kWh/tonne dry','假想碎漿電耗~Hypothetical pulping electricity','比較兩種處理時間下未解離片與纖維長度。~Compare unliberated flakes and fiber length at two durations.','只追求無紙片可能犧牲纖維強度。~Eliminating every flake may sacrifice fiber strength.','碎漿時間越長就永遠越有利。~Longer pulping is always better.'),
 U('粗篩與黏著污染~Coarse screening and stickies','篩選分離大雜質，黏著污染可能變形穿過；溫度和剪切會改變形態。~Screens remove large contaminants; deformable stickies may pass and change with temperature and shear.','reject mass=feed solids*reject fraction;900*0.04','900*0.04',36,'kg','乾固體排渣量~Dry-solids reject mass','比較排渣中的纖維與塑膠比例。~Compare fiber and plastic fractions in rejects.','排渣率提高可能增加纖維損失而非只去雜質。~More rejects can mean more fiber loss, not just contaminant removal.','排渣越多就代表成品品質一定越好。~More rejects necessarily mean better product.'),
 U('油墨疏水性與氣泡~Ink hydrophobicity and bubbles','浮選以油墨顆粒附著氣泡上浮，選擇性取決於表面化學、顆粒與氣泡尺度。~Ink attaches to rising bubbles; selectivity depends on surface chemistry and particle/bubble size.','bubble surface per gas volume=6/d;d=0.001m','6/0.001',6000,'m2/m3','單一直徑球泡，忽略合併~Monodisperse spherical bubbles without coalescence','比較兩種氣泡尺寸並討論表面積與夾帶。~Compare two bubble sizes and discuss area and entrainment.','氣泡過小並非無條件更好，可能增加水與纖維夾帶。~Smaller bubbles are not unconditionally better and may increase entrainment.','氣泡越小就一定完全沒有纖維損失。~Smaller bubbles guarantee no fiber loss.'),
 U('油墨去除與有效速率~Ink removal and effective rate','簡化一級模型可比較實驗，但速率會受氣量、化學與進料改變。~A simple first-order model compares tests, but rate depends on air, chemistry and feed.','remaining fraction=exp(-k t);k=0.4/min;t=3min','exp(-0.4*3)',0.301194212,'fraction','假想有效速率，非設備保證~Hypothetical effective rate, not equipment guarantee','在相同進料改變氣量，重新估計k。~Vary air at fixed feed and re-estimate k.','沿用不同油墨的k會錯估去除。~Using k from another ink misestimates removal.','所有印刷油墨具有同一浮選速率。~Every printing ink has the same flotation rate.'),
 U('浮渣纖維損失~Fiber loss in froth','泡沫帶走油墨也可能帶走纖維；去墨率和纖維回收需同時量測。~Froth removes ink but can carry fiber; measure ink removal and fiber recovery together.','fiber yield=(900-45)/900','(900-45)/900',0.95,'fraction','假想乾纖維收支~Hypothetical dry-fiber balance','秤量浮渣乾固體並分析其中纖維。~Weigh dry froth solids and determine fiber content.','將所有浮渣都當油墨會高估選擇性。~Treating all froth solids as ink overstates selectivity.','浮渣內不可能含有可用纖維。~Froth cannot contain usable fiber.'),
 U('洗滌濃縮與水耗~Washing, thickening and water use','洗滌能移除細小油墨與溶解物，但濾液循環會回帶污染。~Washing removes fine ink and solubles, but recycled filtrate can return contaminants.','makeup=circulation-purge return;10-7','10-7',3,'m3/h','簡化等體積補水帳目~Simplified equal-volume makeup balance','比較開放與閉合水循環的導電度和白度。~Compare conductivity and brightness in open and closed water loops.','只降低新水量可能使溶解污染累積。~Lower freshwater alone can accumulate dissolved contaminants.','水循環越封閉就永遠不需處理溶解污染。~A closed water loop never needs dissolved-contaminant treatment.'),
 U('白度與殘墨~Brightness and residual ink','白度受纖維、填料和油墨共同影響，需搭配殘墨與強度測試。~Brightness depends on fiber, fillers and ink and needs residual-ink and strength tests.','brightness change=after-before;68-60','68-60',8,'instrument units','儀器指標差，不等於百分去墨率~Instrument-index difference, not ink-removal percentage','對同一樣品同時測白度、殘墨與抗張強度。~Measure brightness, residual ink and tensile strength on the same sample.','漂白變亮不代表所有油墨已被分離。~Brighter bleaching does not mean ink has been physically separated.','白度增加8點就等於去除8%油墨。~An8-point brightness rise means8% ink removal.'),
 U('總收率與流程最佳化~Overall yield and process optimization','串聯各段收率相乘，不能相加；目標是在品質要求下保留最多有用纖維。~Multiply serial yields rather than adding them; preserve useful fiber while meeting quality requirements.','overall yield=0.96*0.95*0.98','0.96*0.95*0.98',0.89376,'fraction','相同乾纖維基準、串聯無旁通~Same dry-fiber basis in serial stages without bypass','將某段收率提高但品質下降的情境納入比較。~Compare a higher-yield stage that worsens quality.','只最佳化一段可能把負擔轉移到後段。~Optimizing one stage can shift the burden downstream.','各段收率90%相加即可得到全廠收率。~Adding90% stage yields gives overall plant yield.')])

